;----------------------------[ CPYVXY/CPYVYX - COPY AND MODIFY VECTORS ]----------------------------

CPYVEC:
; ENTRY	(TEMP1)=MASK FOR X SIGN (0 OR 4)
; (TEMP1+1)=MASK FOR Y SIGN (0 OR 4)
; (X)=COUNT OF VECTORS TO MOVE
; (R0,R1)= @ OF VECTOR LIST
; (R2) = + IF NO X/Y SWAP TO TAKE PLACE
; EXIT	(VGLIST,VGLIST+1)=UPDATED VECTOR LIST POINTER
; (R0,R1),R2 UNMODIFIED
; (Y)=INDEX TO LAST BYTE OF VECTOR TABLE
; USES	A,X,Y,R3,R4
L6246:  LDY #$FF
L6248:  BIT R2                  ;SWAP?
L624A:  BMI CPYVYX              ;YEP

CPYVEC_10:
L624C:  INY
L624D:  INY
L624E:  LDA (R0),Y              ;GET OPCODE BYTE
L6250:  EOR $0A                 ;APPLY ANY SIGN CHANGES
L6252:  STA (VGLIST),Y          ;STUFF IT IN VG RAM
L6254:  DEY                     ;BACK UP TO LSB
L6255:  CMP #$F0                ;SHORT VECTOR?
L6257:  BCS CPYVEC_20           ;YEP.
L6259:  LDA (R0),Y              ;COPY REST
L625B:  STA (VGLIST),Y
L625D:  INY
L625E:  INY
L625F:  LDA (R0),Y
L6261:  STA (VGLIST),Y
L6263:  INY
L6264:  LDA (R0),Y
L6266:  EOR TEMP1               ;APPLY ANY SIGN CHANGES
L6268:  STA (VGLIST),Y

CPYVEC_15:
