L6272:  EOR TEMP1               ;MASK FOR X SIGN
L6274:  STA (VGLIST),Y
L6276:  INY
L6277:  BNE CPYVEC_15           ;ALWAYS

;--------------------------------[ CPYVYX COPY AND MODIFY VECTORS ]---------------------------------

CPYVYX:
; [note] CPYVEC's loop: copy one vector instruction, rotating it via the sign bits
L6279:  INY
L627A:  LDA (R0),Y              ;GET LOW BYTE OF VECTOR INSTRUCTION
L627C:  STA R4                  ;SAVE IT
L627E:  INY
L627F:  LDA (R0),Y              ;GET OPCODE BYTE OF VECTOR
L6281:  CMP #$F0                ;TYPE?
L6283:  BCS CPYVYX_1            ;SHORT
L6285:  INY                     ;LONG. SKIP TO MSB OF X PART
L6286:  INY
L6287:  EOR (R0),Y              ;'A' = (OPCODE + MSB Y) .XOR. (Z + MSB X)
L6289:  AND #$0F                ;'A' = (MSB Y) .XOR. (MSB X)
L628B:  STA R3                  ;SAVE IT
L628D:  EOR (R0),Y              ;'A' = (MSB Y) .XOR. (MSB X) .XOR. (Z + MSB X)
L628F:  EOR TEMP1               ;APPLY SIGN CHANGE
L6291:  STA (VGLIST),Y          ;STUFF (Z + MSB Y) TO VG
L6293:  DEY                     ;BACK UP TO LS PART OF X
L6294:  LDA (R0),Y              ;GET LS X
L6296:  PHA                     ;SAVE IT
L6297:  LDA R4                  ;GET LS Y
L6299:  STA (VGLIST),Y          ;STUFF IT TO VG
L629B:  DEY                     ;BACK UP TO OPCODE BYTE
L629C:  LDA R3                  ;GET (MSB Y) .XOR. (MSB X)
L629E:  EOR $0A                 ;APPLY SIGN CHANGE
L62A0:  EOR (R0),Y              ;'A' = (MSB Y) .XOR. (MSB X) .XOR. (OPCODE + MSB Y)
L62A2:  STA (VGLIST),Y          ;STUFF (OPCODE + MSB X) TO VG RAM
L62A4:  DEY                     ;BACK UP TO FIRST BYTE OF INSTRUCTION
L62A5:  PLA                     ;GET LS X
L62A6:  STA (VGLIST),Y          ;PUT IT IN VG RAM
L62A8:  INY                     ;SKIP UP TO NEXT WORD
L62A9:  INY

CPYVYX_5:
L62AA:  INY
L62AB:  DEX                     ;COUNT
L62AC:  BPL CPYVYX              ;CONTINUE
L62AE:  JMP VGADD               ;($7A67)

CPYVYX_1:
L62B1:  EOR R4                  ;'A' = (Z + XAS + X) .XOR. (OPCODE + YAS + Y)
L62B3:  AND #$07                ;'A' = X .XOR. Y
L62B5:  PHA                     ;SAVE IT
L62B6:  EOR (R0),Y              ;'A' = X .XOR. Y .XOR. (OPCODE + YAS + Y)
L62B8:  EOR $0A                 ;APPLY ANY SIGN CORRECTION
L62BA:  STA (VGLIST),Y          ;STUFF (OPCODE + YAS + X) TO VG RAM
L62BC:  DEY                     ;BACK UP
L62BD:  PLA                     ;'A' = X .XOR. Y
L62BE:  EOR (R0),Y              ;'A' = (Z + XAS + X) .XOR. Y .XOR. X
L62C0:  EOR TEMP1               ;APPLY ANY SIGN CORRECTION
L62C2:  STA (VGLIST),Y          ;STUFF (Z + XAS + Y) TO VG RAM
L62C4:  BCS CPYVYX_5            ;(ALWAYS; CARRY STILL SET FROM ENTRY)

;------------------------------[ DSTRCT-DESTRUCTION DURING COLLISION ]------------------------------

DSTRCT:
