L6A10:  LDA RANDOM              ;RANDOM NUMBER
L6A13:  LSR A
L6A14:  AND #$1F
L6A16:  BCC RNDPOS_50           ;START ON X ARIS
L6A18:  CMP #$18                ;START ON Y AXIS
L6A1A:  BCC RNDPOS_35           ;IF 0 TO 767
L6A1C:  AND #$17                ;384 TO 512

RNDPOS_35:
L6A1E:  STA OBJYH,X
L6A21:  LDA #$00
L6A23:  STA OBJXH,X
L6A26:  STA OBJXL,X
L6A29:  BEQ RNDPOS_60           ;ALWAYS

RNDPOS_50:
L6A2B:  STA OBJXH,X
L6A2E:  LDA #$00
L6A30:  STA OBJYH,X
L6A33:  STA OBJYL,X

RNDPOS_60:
L6A36:  RTS

NEWSHP:
; [note] Put the ship at the centre, still, with full shields
L6A37:  LDA #$60
L6A39:  STA SHPXL               ;POSITION IN MIDDLE - JUST OFF CENTER
L6A3C:  STA SHPYL
L6A3F:  LDA #$00
L6A41:  STA SHPXI               ;WITH NO VELOCITY
L6A44:  STA SHPYI
L6A47:  LDA #$10
L6A49:  STA SHPXH
L6A4C:  LDA #$0C
L6A4E:  STA SHPYH
L6A51:  LDA #$FF
L6A53:  STA SHLDS               ;GIVE 'EM FULL SHIELDS
L6A56:  RTS

;----------------------------[ NEWVEL - NEW RANDOM VELOCITY USING OLD ]-----------------------------

NEWVEL:
; [note] New random velocity from the old one
L6A57:  LDA RANDOM              ;RANDOM NUMBER
L6A5A:  AND #$8F
L6A5C:  BPL NEWVEL_10           ;IF POSITIVE NUMBER 0 TO 15
L6A5E:  ORA #$F0                ;-1 TO -16

NEWVEL_10:
L6A60:  CLC
L6A61:  ADC XINC,Y
L6A64:  JSR NEWVE1              ;($6A7E) CHECK RANGE OF VELOCITIES
L6A67:  STA XINC,X
L6A6A:  LDA RANDOM              ;RANDOM NUMBER
L6A6D:  AND #$8F
L6A6F:  BPL NEWVEL_40           ;POSITIVE NUMBER 0 TO 15
L6A71:  ORA #$F0                ;NEGATIVE -1 TO -16

NEWVEL_40:
L6A73:  CLC
L6A74:  ADC YINC,Y
L6A77:  JSR NEWVE1              ;($6A7E) CHECK RANGE OF VELOCITY
L6A7A:  STA YINC,X
L6A7D:  RTS

NEWVE1:
; [note] Range-limit a velocity
L6A7E:  BPL NEWVE1_20           ;POSITIVE RESULT
L6A80:  CMP #$E1
L6A82:  BCS NEWVE1_15           ;WITHIN RANGE
L6A84:  LDA #$E1

NEWVE1_15:
L6A86:  CMP RVELM
L6A88:  BCC RTS_2               ;NOT TOO CLOSE TO ZERO
L6A8A:  LDA RVELM               ;AT LEAST 1/2
L6A8C:  RTS

NEWVE1_20:
L6A8D:  CMP RVELP
L6A8F:  BCS NEWVE1_25           ;NOT TOO CLOSE TO ZERO
L6A91:  LDA RVELP

NEWVE1_25:
L6A93:  CMP #$20
L6A95:  BCC RTS_2               ;WITHIN RANGE
L6A97:  LDA #$1F

RTS_2:
; [note] Shared return
L6A99:  RTS

;-----------------------------------[ PARAMS-DISPLAY PARAMETERS ]-----------------------------------

PARAMS:
; [note] Display the score, lives and messages for this frame
L6A9A:  LDA NPLAYR              ;ATTRACT?
L6A9C:  BEQ PARAMS_12           ;YES,STANDARD SIZE CHAR AND NO COPYRIGHT
L6A9E:  LDA #$81
L6AA0:  LDX #$C3
L6AA2:  JSR VGADD2              ;($7CCC)
L6AA5:  LDY #$00                ;INIT FOR SMALL
L6AA7:  LDA PLAYR               ;PLAYER UP?
L6AA9:  BNE PARAMS_11           ;NO,GIVE 'EM SMALL

PARAMS_12:
L6AAB:  LDY #$10

PARAMS_11:
L6AAD:  STY VGSIZE
L6AAF:  LDA #$19
L6AB1:  LDX #$DB
L6AB3:  JSR VGSABS              ;($7A31) POSITION BEAM
L6AB6:  LDA #$70
L6AB8:  JSR VGWAIT              ;($7AFC) WAIT FOR BEAM
L6ABB:  LDA NPLAYR
L6ABD:  CMP #$02
L6ABF:  BCC PARAMS_10           ;IF ATTRACT OR NOT 2 PLAYER
L6AC1:  LDA PLAYR
L6AC3:  BNE PARAMS_10           ;IF PLAYER 2 UP
L6AC5:  LDA SHPPIX
L6AC8:  BNE PARAMS_10           ;IF HE HAS APPEARED
L6ACA:  LDA SDELAY
L6ACD:  BMI PARAMS_10           ;HE HAS DIED
L6ACF:  LDA FRAME
L6AD1:  AND #$10
L6AD3:  BEQ PARAMS_20           ;FLASH SCORE

PARAMS_10:
L6AD5:  LDA #$62
L6AD7:  LDY #$03
L6AD9:  SEC
L6ADA:  JSR DIGITS              ;($7C98) DISPLAY PLAYER 1 SCORE

PARAMS_20:
L6ADD:  LDY HITS
L6ADF:  LDA #$00                ;PLAYER 1
L6AE1:  JSR GTSP                ;($6B90) GET SHIP PIX
L6AE4:  LDA #$28
L6AE6:  JSR LIVES               ;($7C72) DISPLAY NUMBER OF LIFES
L6AE9:  LDA PLAYR               ;PLAYER UP?
L6AEB:  BNE PARAMS_22           ;NOPE
L6AED:  LDA SHPPIX              ;ALIVE?
L6AF0:  BMI PARAMS_22           ;NO
L6AF2:  BEQ PARAMS_22           ;NO
L6AF4:  JSR TWO                 ;($6BA5) GO TWINKLE OFF SCREEN

PARAMS_22:
L6AF7:  LDA #$00                ;SMALL
L6AF9:  STA VGSIZE
L6AFB:  ORA $24
L6AFD:  ORA $25                 ;HIGH SCORE?
L6AFF:  BEQ PARAMS_21           ;NO. NEVER MIND WRITING IT
L6B01:  LDA #$74
L6B03:  LDX #$DB
L6B05:  JSR VGSABS              ;($7A31) POSITION BEAM
L6B08:  LDA #$50
L6B0A:  JSR VGWAIT              ;($7AFC) WAIT FOR BEAM
L6B0D:  LDA #$23
L6B0F:  LDY #$03
L6B11:  SEC
L6B12:  JSR DIGITS              ;($7C98) DISPLAY HIGH SCORE
L6B15:  LDY #$00
L6B17:  STY R3
L6B19:  JSR VGCHAR              ;($7A0A) BLANK
L6B1C:  JSR IN3TIM              ;($6D5E) 3 INITIALS

PARAMS_21:
L6B1F:  LDA NPLAYR              ;ATTRACT?
L6B21:  BEQ PARAMS_23           ;YES, NO BONUS
L6B23:  LDA $FF                 ;BONUS?
L6B25:  BMI PARAMS_23           ;NO BONUS MSG
L6B27:  LDY #$0D                ;BONUS MESSAGE
L6B29:  LDA #$00                ;ENGLISH ONLY
L6B2B:  JSR VGME                ;($7198)
L6B2E:  LDA #$68
L6B30:  CLC
L6B31:  ADC PLAYR3              ;COMPUTE @
L6B33:  LDY #$03
L6B35:  SEC
L6B36:  JSR DIGITS              ;($7C98)

PARAMS_23:
L6B39:  LDX #$10                ;MEDIUM SIZE
L6B3B:  LDA NPLAYR
L6B3D:  CMP #$01
L6B3F:  BEQ RTS_5               ;NO PLAYER 2
L6B41:  BCC PARAMS_24           ;ATTRACT. ALWAYS BIG
L6B43:  LDA PLAYR               ;PLAYER 2 UP?
L6B45:  BNE PARAMS_24           ;YES. GIVE 'EM BIG
L6B47:  TAX                     ;SMALL

PARAMS_24:
L6B48:  STX VGSIZE
L6B4A:  LDA #$C0
L6B4C:  LDX #$DB
L6B4E:  JSR VGSABS              ;($7A31) POSITION BEAM
L6B51:  LDA #$50
L6B53:  JSR VGWAIT              ;($7AFC) WAIT FOR BEAM
L6B56:  LDA NPLAYR              ;ATTRACT?
L6B58:  BEQ PARAMS_30           ;YEP. ALWAYS DISPLAY
L6B5A:  LDA PLAYR
L6B5C:  BEQ PARAMS_30           ;PLAYER NOT UP
L6B5E:  LDA SHPPIX
L6B61:  BNE PARAMS_30           ;IF HE HAS APPEARED
L6B63:  LDA SDELAY
L6B66:  BMI PARAMS_30           ;HE HAS DIED
L6B68:  LDA FRAME
L6B6A:  AND #$10
L6B6C:  BEQ PARAMS_40           ;FLASH SCORE

PARAMS_30:
L6B6E:  LDA #$65
L6B70:  LDY #$03
L6B72:  SEC                     ;ZERO SUPPRESS
L6B73:  JSR DIGITS              ;($7C98) DISPLAY SCORE FOR PLAYER 2

PARAMS_40:
L6B76:  LDY $70
L6B78:  LDA #$01                ;PLAYER 2
L6B7A:  JSR GTSP                ;($6B90) GET SHIP PIX
L6B7D:  LDA #$CF
L6B7F:  JSR LIVES               ;($7C72) DISPLAY NUMBER OF LIVES
L6B82:  LDA PLAYR               ;PLAYER 2 UP?
L6B84:  BEQ RTS_5               ;NOPE
L6B86:  LDA SHPPIX              ;ALIVE?
L6B89:  BEQ RTS_5               ;NOPE
L6B8B:  BMI RTS_5               ;NOPE
L6B8D:  JMP TWO                 ;($6BA5) DO TWINKLE

GTSP:
; AT EXIT:
; (Y)=# OF HITS-1 IF SHIP VISIBLE
; ELSE # OF HITS
L6B90:  EOR PLAYR               ;GET PLAYER
L6B92:  BEQ GTSP_1              ;WANT 1, IS 1
L6B94:  LDX $0319               ;WANT 2, IS 1
L6B97:  BMI GTSP_3              ;BLOWING UP
L6B99:  BNE GTSP_2              ;VISIBLE

GTSP_3:
; OR WANT 1, IS 2
L6B9B:  INY                     ;NOT VISIBLE

GTSP_2:
L6B9C:  RTS

GTSP_1:
L6B9D:  LDX SHPPIX              ;WANT 1, IS 1
L6BA0:  BEQ GTSP_3              ;NOT VISIBLE
L6BA2:  BMI GTSP_3              ;BLOWING UP

RTS_5:
; WANT 2, IS 2
L6BA4:  RTS                     ;VISIBLE

TWO:
; [note] Ramp the returning ship's intensity up (the back-to-life twinkle)
L6BA5:  LDA SBTL                ;GET SHIP INTENSITY
L6BA7:  CMP #$C0                ;AT MAX?
L6BA9:  BCC TWO_1               ;NOPE. TWINKLE
L6BAB:  RTS                     ;YEP. JUST EXIT

TWO_1:
L6BAC:  PHA                     ;SAVE SBTL VALUE
L6BAD:  EOR #$FF                ;NEGATE IT
L6BAF:  ADC #$C1                ;COMPUTE 0C0-SBTL
L6BB1:  STA SBTL                ;PASS IT TO SHPPIC ROUTINE
L6BB3:  LDA ANGLE               ;SAVE CURRENT ANGLE
L6BB5:  PHA
L6BB6:  LDA #$40                ;90 DEGREES
L6BB8:  STA ANGLE
L6BBA:  JSR SHPPIC              ;($6E3C) DRAW A TWINKLE SHIP
L6BBD:  PLA                     ;RESTORE STUFF
L6BBE:  STA ANGLE
L6BC0:  PLA
L6BC1:  STA SBTL
L6BC3:  RTS                     ;DONE

;---------------------------------[ PICTUR-DISPLAY OBJECT PICTURE ]---------------------------------

PICTUR:
; ENTRY (Y)=SCALING FACTOR TO BE USED
; (XCOMP,XCOMP+3)=OBJECT POSITION
L6BC4:  STY VGSIZE              ;SET SCALING FACTOR
L6BC6:  STX TEMP3               ;SAVE X
L6BC8:  LSR $06                 ;PUT VALUES INTO INTEGER FORMAT
L6BCA:  ROR XCOMP
L6BCC:  LSR $06
L6BCE:  ROR XCOMP
L6BD0:  LSR $06
L6BD2:  ROR XCOMP
L6BD4:  LSR $08
L6BD6:  ROR $07
L6BD8:  LSR $08
L6BDA:  ROR $07
L6BDC:  INC $08                 ;ADD 128 (RANGE IS 127<Y<897)
L6BDE:  LSR $08
L6BE0:  ROR $07
L6BE2:  JSR POSBEM              ;($6C43) POSITION BEAM
L6BE5:  LDX TEMP3
L6BE7:  JSR PICTUR_31           ;($6BED)
L6BEA:  LDX TEMP3               ;THE FOLLOWING CODE ALWAYS RETURNS HERE
L6BEC:  RTS

PICTUR_31:
L6BED:  LDA OBJ,X
L6BF0:  BPL PICTUR_35           ;IF NOT EXPLODING
L6BF2:  CPX #$19
L6BF4:  BEQ PICTUR_33           ;IF THE SHIP
L6BF6:  AND #$0C
L6BF8:  LSR A                   ;0, 2, 4 OR 6
L6BF9:  TAY
L6BFA:  LDA EXPPIC,Y
L6BFD:  LDX EXPPIC+1,Y
L6C00:  BNE PICTUR_78           ;ALWAYS

PICTUR_33:
L6C02:  JMP SHPEXP              ;($6D77) EXPLODE SHIP

PICTUR_35:
L6C05:  CPX #$19
L6C07:  BEQ PICTUR_50           ;IF THE SHIP
L6C09:  CPX #$1A
L6C0B:  BEQ PICTUR_60           ;IF SAUCER
L6C0D:  BCS PICTUR_70           ;IF A TORPEDO (DOT)
L6C0F:  ASL A
L6C10:  BPL PICTUR_37
L6C12:  JMP TRIPIX              ;($4A6D)

PICTUR_37:
L6C15:  LSR A
L6C16:  LSR A
L6C17:  LSR A
L6C18:  AND #$06
L6C1A:  TAY
L6C1B:  LDA ROCKSA,Y
L6C1E:  LDX ROCKSA+1,Y

PICTUR_78:
L6C21:  JMP VGADD2              ;($7CCC) ADD JSRL OF PICTURE TO VECTOR LIST

PICTUR_50:
L6C24:  JSR SHLDPX              ;($669D) DISPLAY THE SHIELD IF ENABLED
L6C27:  JMP SHPPIC              ;($6E3C) DISPLAY SHIP PICTURE

PICTUR_60:
L6C2A:  LDA #$34
L6C2C:  LDX #$C7
L6C2E:  BNE PICTUR_78           ;ALWAYS

PICTUR_70:
L6C30:  LDA #$70
L6C32:  LDX #$F0
L6C34:  JSR VGDOT               ;($7AFE) PUT A DOT THERE
L6C37:  LDX TEMP3
L6C39:  LDA FRAME
L6C3B:  AND #$03
L6C3D:  BNE PICTUR_75           ;EVERY FOURTH FRAME
L6C3F:  DEC OBJ,X               ;DECREMENT ACTIVE COUNT

PICTUR_75:
L6C42:  RTS

POSBEM:
; [note] Position the beam, then wait for it
L6C43:  LDX #$05
L6C45:  JSR VGLABS              ;($7A4A) POSITION BEAM
L6C48:  LDA #$70                ;WE WANT A WAIT OF 7
L6C4A:  SEC
L6C4B:  SBC VGSIZE              ;BACK DOWN BY AMOUNT OF SCALE

POSBEM_28:
L6C4D:  CMP #$A0                ;TOO BIG?
L6C4F:  BCC POSBEM_30           ;NOPE. (0-90)
L6C51:  PHA                     ;SAVE IT
L6C52:  LDA #$90
L6C54:  JSR VGWAIT              ;($7AFC) INSERT A WAIT
L6C57:  PLA
L6C58:  SEC
L6C59:  SBC #$10                ;BACK DOWN AGAIN
L6C5B:  BNE POSBEM_28           ;(ALWAYS)

POSBEM_30:
L6C5D:  JMP VGWAIT              ;($7AFC) INSERT A WAIT AND EXIT

;----------------------------------[ POINTS-ADD POINTS TO SCORE ]-----------------------------------

POINTS:
; ENTRY:
; A+CARRY=# TO ADD TO POINTS (/100)
; AT EXIT:
; SCORE(PLAYR)=SCORE(PLAYR)+A*1000+CARRY*10000
L6C60:  ROR A
L6C61:  ROR R0
L6C63:  LSR A
L6C64:  ROR R0
L6C66:  LSR A
L6C67:  ROR R0
L6C69:  LSR A
L6C6A:  ROR R0
L6C6C:  STA R1
L6C6E:  SED
L6C6F:  STX R2                  ;SAVE X
L6C71:  LDX PLAYR3
L6C73:  LDA R0
L6C75:  AND #$F0                ;LOW DIGIT ALWAY=0
L6C77:  CLC
L6C78:  ADC SCORE,X
L6C7A:  STA SCORE,X
L6C7C:  LDA R1
L6C7E:  ADC $63,X
L6C80:  STA $63,X
L6C82:  LDA #$00
L6C84:  ADC $64,X
L6C86:  STA $64,X
L6C88:  CMP $6A,X               ;HIT THE NEXT PLATEAU?
L6C8A:  BCC POINTS_19           ;NOPE. NEVER MIND
L6C8C:  BNE POINTS_10           ;YEP.
L6C8E:  LDA $63,X               ;CHECK NEXT BYTE DOWN
L6C90:  CMP $69,X
L6C92:  BCC POINTS_19           ;OK

POINTS_10:
L6C94:  CLC                     ;HIT LIMIT
L6C95:  LDA $FE                 ;SO UP IT A NOTCH
L6C97:  ADC $69,X
L6C99:  STA $69,X
L6C9B:  LDA $FF
L6C9D:  ADC $6A,X
L6C9F:  STA $6A,X
L6CA1:  LDX PLAYR
L6CA3:  LDA HITS,X
L6CA5:  CMP #$0A                ;NO MORE THAN 10 LIVES
L6CA7:  BCS POINTS_19
L6CA9:  INC HITS,X              ;GIVE 'EM ANOTHER LIFE
L6CAB:  INC SND3                ;SIGNAL THAT WE MUST MAKE NOISE

POINTS_19:
L6CAD:  CLD
L6CAE:  LDX R2                  ;RESTORE X
L6CB0:  RTS

;------------------------------------[ SBANK - SET BANK SELECT ]------------------------------------

SBANK:
; [note] Select the current player's RAM page
L6CB1:  LDA PLAYR               ;0 OR 1
L6CB3:  LSR A
L6CB4:  ROR A                   ;0 OR 80
L6CB5:  STA BNKSEL
L6CB8:  RTS

;--------------------------------[ SCORES-DISPLAY HIGH SCORE TABLE ]--------------------------------

SCORES:
; (CC)=CARRY SET IF DISPLAYING TABLE
L6CB9:  LDX NPLAYR
L6CBB:  BNE SCORES_40           ;NOT ATTRACT MODE
L6CBD:  LDA $77
L6CBF:  AND #$04
L6CC1:  BEQ SCORES_30           ;DISPLAY SCORES

SCORES_90:
L6CC3:  STX VGSIZE
L6CC5:  LDA #$70
L6CC7:  LDX #$68
L6CC9:  JSR VGSABS              ;($7A31) POSITION BEAM
L6CCC:  LDA #$70
L6CCE:  JSR VGWAIT              ;($7AFC) WAIT
L6CD1:  JSR CPYRS               ;($717E) PUT UP COPY RIGHT
L6CD4:  LDY #$07
L6CD6:  JSR VGMSG               ;($718F) GAME OVER

SCORES_40:
L6CD9:  CLC
L6CDA:  RTS

SCORES_30:
L6CDB:  LDA HSCORE
L6CDD:  ORA $24
L6CDF:  ORA $25
L6CE1:  BEQ SCORES_90           ;IF NO HIGH SCORES
L6CE3:  LDY #$00
L6CE5:  JSR VGMSG               ;($718F) DISPLAY "HIGH SCORE" MESSAGE
L6CE8:  LDX #$00
L6CEA:  STX R0                  ;ITEM COUNTR (COUNTS BY 1 IN BCD)
L6CEC:  STX R3                  ;ITEM COUNTER (COUNTS BY 3 IN BINARY)
L6CEE:  LDA #$A7
L6CF0:  STA R2                  ;Y VALUE FOR FIRST LINE OF DISPLAY
L6CF2:  LDX #$23

SCORES_20:
L6CF4:  LDA #$10
L6CF6:  STA VGSIZE              ;CHARACTER SIZE
L6CF8:  STX R1                  ;SCORE INDEX
L6CFA:  LDA $00,X               ;ANY SCORE?
L6CFC:  ORA VGSIZE,X
L6CFE:  ORA VGBRIT,X
L6D00:  BEQ SCORES_80           ;A 0 ENDS THE SEARCH
L6D02:  LDA #$5F                ;VALUE OF X FOR LINE
L6D04:  LDX R2                  ;GET Y
L6D06:  JSR VGSABS              ;($7A31) POSITION BEAM
L6D09:  LDA #$40
L6D0B:  JSR VGWAIT              ;($7AFC) WAIT FOR IT
L6D0E:  LDA R0                  ;UPDATE BCD ITEM COUNTER
L6D10:  SED
L6D11:  CLC
L6D12:  ADC #$01
L6D14:  CLD
L6D15:  STA R0
L6D17:  LDA #$10                ;GET ADDRESS OF ITEM COUNTER
L6D19:  SEC                     ;SUPPRESS LEADING ZERO'S
L6D1A:  LDY #$01                ;ONLY 2 DIGITS (1 BYTE)
L6D1C:  JSR DIGITS              ;($7C98)
L6D1F:  LDA #$40
L6D21:  TAX
L6D22:  JSR VGDOT               ;($7AFE) PRINT A PERIOD AFTER NUMBER
L6D25:  LDY #$00
L6D27:  JSR VGCHAR              ;($7A0A) PRINT A SPACE AFTER THAT
L6D2A:  LDA R1                  ;'A' = ADDRESS OF 3 BYTE SCORE
L6D2C:  LDY #$03                ;6 DIGITS (3 BYTES)
L6D2E:  SEC                     ;SUPPRESS LEADING ZEROES
L6D2F:  JSR DIGITS              ;($7C98)
L6D32:  LDY #$00
L6D34:  JSR VGCHAR              ;($7A0A) FOLLOW WITH A BLANK
L6D37:  JSR IN3TIM              ;($6D5E) DISPLAY 3 INITIALS
L6D3A:  LDA R0
L6D3C:  CMP #$04                ;ONE OF FIRST 3?
L6D3E:  BCS SCORES_21           ;NO
L6D40:  LDA R2                  ;PUT IN JSRL TO SHIP
L6D42:  ADC #$02
L6D44:  TAX                     ;Y POSITION
L6D45:  LDA #$B2                ;X POSITION
L6D47:  LDY #$02                ;# OF LIVES
L6D49:  JSR LIVESS              ;($7C74)

SCORES_21:
L6D4C:  LDA R2                  ;GET 'Y' POSITION
L6D4E:  SEC                     ;BACK DOWN
L6D4F:  SBC #$08                ;COMPUTE Y OF NEXT LINE
L6D51:  STA R2
L6D53:  LDX R1                  ;GET SCORE INDEX
L6D55:  INX                     ;+3
L6D56:  INX
L6D57:  INX
L6D58:  CPX #$41                ;END?
L6D5A:  BCC SCORES_20           ;NOPE

SCORES_80:
L6D5C:  SEC                     ;YEP. SIGNAL SCORES ARE UP
L6D5D:  RTS

IN3TIM:
; [note] Display all three initials: INITAL for each
L6D5E:  JSR IN3TIM_1            ;($6D64)
L6D61:  JSR IN3TIM_1            ;($6D64)

IN3TIM_1:
L6D64:  LDY R3                  ;Y = INITIAL INDEX
L6D66:  JSR INITAL              ;($66E1) DISPLAY INITIAL
L6D69:  INC R3                  ;BUMP POINTER
L6D6B:  RTS

;------------------------------[ SEARCH - SEARCH FOR FREE ROCK ENTRY ]------------------------------

SEARCH:
; [note] Find a free rock slot, from X down; $FF if none
L6D6C:  LDX #$18

SEARC1:
; [note] SEARCH's loop entry
L6D6E:  LDA OBJ,X
L6D71:  BEQ SEARC1_20           ;FOUND ONE
L6D73:  DEX
L6D74:  BPL SEARC1              ;LOOP TIL EXHAUSTED

SEARC1_20:
L6D76:  RTS

;--------------------------------[ SHPEXP-SHIP EXPLODING PICTURES ]---------------------------------

SHPEXP:
; [note] The ship's explosion: move and draw its fragments
L6D77:  LDA SHPPIX
L6D7A:  CMP #$A2
L6D7C:  BCS SHPEXP_10           ;NOT THE FIRST EXPLOSION
L6D7E:  LDX #$07                ;# OF VECTORS IN SHIP PICTURE

SHPEXP_5:
L6D80:  LDA RANDOM
L6D83:  AND #$07
L6D85:  EOR XCOMP               ;APPLY IT TO THE POSITION
L6D87:  ASL A                   ;SCALE IT
L6D88:  STA SXPXL,X             ;X LSB
L6D8B:  LDA $06
L6D8D:  ROL A
L6D8E:  STA SXPXH,X             ;X MSB
L6D91:  LDA RANDOM
L6D94:  AND #$07
L6D96:  EOR $07                 ;ADD IT TO POSITION
L6D98:  ASL A                   ;SCALE IT
L6D99:  STA SXPYL,X             ;Y LSB
L6D9C:  LDA $08
L6D9E:  ROL A
L6D9F:  STA SXPYH,X             ;Y MSB
L6DA2:  LDA RANDOM
L6DA5:  AND #$0F
L6DA7:  ADC #$F8
L6DA9:  STA EXPTMB,X
L6DAC:  JSR SHPEXP_150          ;($6E31)
L6DAF:  STA EXPDX,X             ;X VEL
L6DB1:  JSR SHPEXP_150          ;($6E31)
L6DB4:  STA EXPDY,X             ;Y VELOCITY
L6DB6:  DEX
L6DB7:  BPL SHPEXP_5            ;CONTINUE

SHPEXP_10:
L6DB9:  LDA #$07
L6DBB:  STA R2                  ;NO X/Y FLIP REQUIRED
L6DBD:  STA R5                  ;LOOP COUNT

SHPEXP_20:
L6DBF:  LDX R5                  ;VECTOR COUNTER
L6DC1:  LDA SHPPIX              ;GET SHIP PICTURE (A0-FF)
L6DC4:  JSR COMP                ;($70EC) A = 60 - 0 IN INCREMENTS OF 1
L6DC7:  AND #$F0                ;60 - 0 IN INCREMENTS OF 10
L6DC9:  ADC #$60                ;CO - 60
L6DCB:  STA TEMP1               ;INTENSITY
L6DCD:  LDA EXPANG,X            ;ORIENTATION
L6DCF:  ADC EXPTMB,X            ;UPDATE IT
L6DD2:  STA EXPANG,X
L6DD4:  LSR A                   ;GET CODE
L6DD5:  LSR A
L6DD6:  PHA                     ;SAVE IT FOR LATER
L6DD7:  LSR A                   ;PUT IT IN BIT 2
L6DD8:  LSR A
L6DD9:  LSR A
L6DDA:  AND #$04                ;ISOLATE BIT 2
L6DDC:  STA $0A                 ;Y INVERSION BIT
L6DDE:  ORA TEMP1               ;MERGE IT WITH INTENSITY
L6DE0:  STA TEMP1               ;PASS IT
L6DE2:  JSR SHPEXP_100          ;($6E12) COMPUTE X
L6DE5:  STA $06                 ;MOVE DATA BACK TO X SLOT
L6DE7:  LDA $07
L6DE9:  STA XCOMP
L6DEB:  TXA
L6DEC:  CLC
L6DED:  ADC #$08                ;SKIP UP TO Y PARAMETERS
L6DEF:  TAX
L6DF0:  JSR SHPEXP_100          ;($6E12) COMPUTE THEM
L6DF3:  JSR POSBEM              ;($6C43) POSITION BEAM
L6DF6:  PLA                     ;GET ORIENTATION
L6DF7:  AND #$1E                ;ISOLATE PIX CODE
L6DF9:  TAX
L6DFA:  LDA L506A,X             ;POINT TO FRAME ROUTINE
L6DFD:  ASL A                   ;ITS A JSRL SO WE MUST UNPACK IT
L6DFE:  STA R0                  ;AND PUT THE ACTUAL ADDRESS INTO R0,R1
L6E00:  LDA L506B,X
L6E03:  ROL A
L6E04:  EOR #$C0                ;DROP BIT 15 AND SET BIT 14
L6E06:  STA R1
L6E08:  LDX #$00
L6E0A:  JSR CPYVEC              ;($6246) MOVE IN 1 VECTOR
L6E0D:  DEC R5                  ;COUNT DOWN
L6E0F:  BPL SHPEXP_20           ;CONTINUE
L6E11:  RTS                     ;EXIT

SHPEXP_100:
L6E12:  LDY #$00
L6E14:  LDA EXPDX,X             ;GET DIRECTION
L6E16:  BPL SHPEXP_101
L6E18:  DEY                     ;SIGN EXTEND

SHPEXP_101:
L6E19:  CLC
L6E1A:  ADC SXPXL,X             ;UPDATE POSITION
L6E1D:  STA SXPXL,X
L6E20:  STA $07                 ;PASS IT TO VGLABS ROUTINE HERE
L6E22:  TYA
L6E23:  ADC SXPXH,X
L6E26:  AND #$07                ;ROLL OVER TOP AND SIDES
L6E28:  STA SXPXH,X
L6E2B:  LSR A
L6E2C:  STA $08
L6E2E:  ROR $07
L6E30:  RTS

SHPEXP_150:
L6E31:  LDA RANDOM
L6E34:  AND #$07                ;MASK TO 3 BITS
L6E36:  CLC
L6E37:  ADC #$FC                ;MAKE IT RANGE -4 < N < +3
L6E39:  ADC #$00                ;MAKE IT RANGE -4 < N < +4
L6E3B:  RTS

;----------------------------------[ SHPPIC-DISPLAY SHIP PICTURE ]----------------------------------

SHPPIC:
; [note] Draw the ship, and its flame when thrusting
L6E3C:  LDA SBTL
L6E3E:  CMP #$C0                ;TWINKLE ON THE SCREEN?
L6E40:  BCS SHPPIC_1            ;NOPE
L6E42:  ADC #$06                ;YEP. TWINKLE
L6E44:  STA SBTL
L6E46:  LDA RANDOM              ;RANDOM NUMBER
L6E49:  AND #$04                ;GET RANDOM INVERSION BITS
L6E4B:  STA TEMP1
L6E4D:  LDA RANDOM              ;RANDOM NUMBER
L6E50:  AND #$04
L6E52:  STA $0A
L6E54:  LDA RANDOM              ;RANDOM NUMBER
L6E57:  AND #$80
L6E59:  STA R2
L6E5B:  LDA #$09                ;10 PAIRS OF VECTORS
L6E5D:  STA R5
L6E5F:  LDA #$4D
L6E61:  LDX #$87
L6E63:  STA R1                  ;INIT R0,R1
L6E65:  STX R0
L6E67:  LDY #$00                ;0=> Y
L6E69:  LDX #$00

SHPPIC_2:
L6E6B:  JSR AYTOR0              ;($6EB2) COMPUTE R0,R1 = Y+1, COPY 1 VECTOR
L6E6E:  LDA RANDOM              ;RANDOM NUMBER
L6E71:  LSR A                   ;PUT IT IN CARRY
L6E72:  LDA #$00
L6E74:  BCC SHPPIC_4            ;SHOW A DOT
L6E76:  LDA #$70                ;BLANK A DOT

SHPPIC_4:
L6E78:  ORA TEMP1               ;MERGE WITH INVERSION BIT
L6E7A:  STA TEMP1
L6E7C:  JSR AYTOR0              ;($6EB2) COMPUTE R0,R1 = Y+1, COPY 1 VECTOR
L6E7F:  LDA TEMP1               ;CLEAR INTENSITY FLAG
L6E81:  AND #$04                ;BUT KEEP INVERSION BIT
L6E83:  STA TEMP1
L6E85:  DEC R5                  ;COUNT
L6E87:  BPL SHPPIC_2            ;CONTINUE
L6E89:  JSR AYTOR0              ;($6EB2) RETURN BEAM TO CENTER AT 0 INTENSITY

SHPPIC_1:
L6E8C:  JSR CPTSPX              ;($6EC1)
L6E8F:  JSR CPYVEC              ;($6246) WITH NO INTENSITY CHANGE
L6E92:  LDA SBTL                ;GET INTENSITY
L6E94:  AND #$F0
L6E96:  CMP #$60                ;THERE IS A MINIMUM INTENSITY
L6E98:  BCS SHPPIC_3
L6E9A:  LDA #$60                ;BELOW WHICH IT CAN'T BE SEEN

SHPPIC_3:
L6E9C:  ORA TEMP1               ;MERGE IN THE X INVERSION BIT
L6E9E:  STA TEMP1
L6EA0:  LDX #$07                ;LOAD X WITH VECTOR COUNT-1 (S/B A 5)
L6EA2:  JSR AYTOR0              ;($6EB2) ADD Y+1 TO R0, COPY VECTORS

THRTST:
; [note] Is the thrust button on?
L6EA5:  BIT THRUST              ;TRUE?
L6EA8:  BPL TTST                ;NO THRUST. EXIT
L6EAA:  LDA FRAME
L6EAC:  AND #$04
L6EAE:  BEQ TTST                ;FLICKER AT 15HZ
L6EB0:  LDX #$01                ;ALL THRUSTS ARE ONLY 2 VECTORS

AYTOR0:
; [note] Advance the source pointer by Y+1, then CPYVEC
L6EB2:  TYA                     ;POINT R0,R1 TO FLAME VECTORS
L6EB3:  SEC                     ;+1
L6EB4:  ADC R0
L6EB6:  STA R0
L6EB8:  LDA #$00
L6EBA:  ADC R1
L6EBC:  STA R1
L6EBE:  JMP CPYVEC              ;($6246) COPY FLAME VECTORS AND EXIT

CPTSPX:
; [note] Point R0/R1 at the ship hull for the current ANGLE
L6EC1:  LDA ANGLE
L6EC3:  SEC
L6EC4:  SBC #$40                ;PICTURES ARE STORED 90-135 SO BACK UP
L6EC6:  JSR CPXROT              ;($6EE2) COMPUTE INDEX INTO ROTATIONS ARRAY
L6EC9:  TYA                     ;Y COMES BACK POINTING TO WORD
L6ECA:  LSR A                   ;FIX IT TO POINT TO BYTE
L6ECB:  TAY
L6ECC:  LDX #$53                ;GET HIGH BYTE OF ADDRESS OF SHIP VECTORS
L6ECE:  LDA SHIPS,Y             ;GET OFFSET
L6ED1:  ASL A                   ;*2
L6ED2:  BCC CPTSPX_5            ;X=X+CARRY
L6ED4:  INX
L6ED5:  CLC

CPTSPX_5:
L6ED6:  ADC #$C6                ;ADD OFFSET TO ADDRESS
L6ED8:  STA R0
L6EDA:  TXA
L6EDB:  ADC #$00
L6EDD:  STA R1
L6EDF:  LDX #$00

TTST:
; [note] Shared return
L6EE1:  RTS

;---------------------------[ CPXROT OBJECT ORIENTATION INDEX EVALUATOR ]---------------------------

CPXROT:
; [note] Object orientation index from the angle
L6EE2:  LSR A                   ;THROW AWAY LOW 2 BITS OF ANGLE
L6EE3:  STA R0                  ;SAVE RESIDUAL
L6EE5:  LSR A
L6EE6:  LSR A                   ;GET THE 1/2 QUADRANT NUMBER
L6EE7:  LSR A
L6EE8:  LSR A
L6EE9:  TAY
L6EEA:  LDA TABLE,Y             ;GET OPERATIONS CODE
L6EED:  ASL A                   ;PUT NEGATE BIT INTO CARRY
L6EEE:  STA R2                  ;SAVE RESIDUAL
L6EF0:  LDA R0                  ;GET ANGLE (/2)
L6EF2:  AND #$0E                ;ISOLATE PORTION WITHIN 45 DEGREES
L6EF4:  BCC CPXROT_1            ;NO NEGATE
L6EF6:  EOR #$0E                ;NEGATE 3 BITS TO 4 BITS
L6EF8:  ADC #$01                ;(CARRY SET FROM ABOVE)

CPXROT_1:
L6EFA:  TAY                     ;PASS IT TO USER
L6EFB:  LDA R2                  ;GET RESIDUAL OPERATIONS BITS
L6EFD:  AND #$04                ;ISOLATE X MASK
L6EFF:  STA TEMP1               ;PASS IT TO USER
L6F01:  ASL R2                  ;PLACE SWAP BIT INTO BIT 7
L6F03:  LDA R2
L6F05:  AND #$04                ;ISOLATE Y MASK
L6F07:  STA $0A                 ;PASS IT TO USER
L6F09:  RTS                     ;FINI

TABLE:
; placed by hand: DSTRD0.MAC:2891 `TABLE: CT 0,0,0,0 ...`, the CPXROT control table: bit 7 negate pix select, 5 swap X with Y, 1 X sign mask, 0 Y sign mask. Eight bytes, one per orientation octant. Built by the CT macro, so the by-content placement cannot see its bytes
L6F0A:  .byte $00, $A3, $22, $81, $03, $A0, $21, $82 ;.."...!.

;------------------------------------[ SOUNDS-GENERATE SOUNDS ]-------------------------------------

SOUNDS:
; [note] Decide which sounds play this frame
L6F12:  LSR R0                  ;ASSUME NO THRUST
L6F14:  LDX NPLAYR
L6F16:  BEQ SOUNDS_60           ;ATTRACT. RESET EXPLOSION
L6F18:  LDX $A9                 ;CHANNELS 6 AND 7 MUST NOT BE BUSY
L6F1A:  BNE SOUNDS_25           ;NO SUCH LUCK. WAIT UNTIL NEXT TIME
L6F1C:  LDA SND3                ;ANY EXTRA LIFE NOISE REQ?
L6F1E:  BEQ SOUNDS_24           ;NOPE
L6F20:  LDY #$2F                ;YEP. START IT
L6F22:  JSR SNDON               ;($775B)
L6F25:  STX SND3                ;CLEAR THE FLAG FOR NEXT TIME
L6F27:  BEQ SOUNDS_25           ;(ALWAYS)

SOUNDS_24:
L6F29:  LDA HSSND               ;ANY HI SCORE NOISE REQ?
L6F2B:  BEQ SOUNDS_25           ;NO.
L6F2D:  LDY #$5F
L6F2F:  JSR SNDON               ;($775B)
L6F32:  STX HSSND               ;CLEAR FLAG FOR NEXT TIME

SOUNDS_25:
L6F34:  LDA SHPPIX              ;SHIP?
L6F37:  BMI SOUNDS_27           ;SHIP IS DESTROYED
L6F39:  BEQ SOUNDS_27           ;SHIP NOT ON SCREEN YET
L6F3B:  ASL THRUST              ;SIGNAL THRUST
L6F3E:  ROR R0
L6F40:  LDA NROCKS
L6F43:  BEQ SOUNDS_27           ;IF NOT ROCKS
L6F45:  LDA THUMP1
L6F47:  BEQ SOUNDS_30           ;IF THUMP SOUND IS OFF
L6F49:  DEC THUMP1
L6F4B:  BNE SOUNDS_50           ;LEAVE SOUND ON

SOUNDS_27:
L6F4D:  LDA THUMP3
L6F50:  STA THUMP2              ;AT LEAST 8 FRAMES BEFORE ITS ON AGAIN
L6F52:  BPL SOUNDS_50           ;ALWAYS

SOUNDS_30:
L6F54:  DEC THUMP2
L6F56:  BNE SOUNDS_50           ;LEAVE SOUND OFF
L6F58:  LDA #$04
L6F5A:  STA THUMP1              ;NUMBER FRAMES FOR SOUND TO BE ON
L6F5C:  INC LTHUMP              ;CHEAP WAY TO TOGGLE BIT 0
L6F5E:  LDA LTHUMP
L6F60:  AND #$01                ;ISOLATE IT
L6F62:  TAX
L6F63:  LDY TSS,X
L6F66:  JSR SNDPON              ;($7758)

SOUNDS_50:
L6F69:  LDA LEXPSND
L6F6B:  TAX
L6F6C:  AND #$3F
L6F6E:  BEQ SOUNDS_60           ;IF NO EXPLOSION VOLUME
L6F70:  DEX

SOUNDS_60:
L6F71:  STX LEXPSND
L6F73:  STX EXPSND              ;SET SOUND FREQUENCY/LEVEL
L6F76:  LDA R0                  ;GET THRUST CONTROL
L6F78:  STA SPTEN               ;TURN ON/OFF THRUST SOUND
L6F7B:  RTS

TSS:
L6F7C:  .byte $07, $0F          ;..

;-------------------------------[ SPLIT - SPLIT ROCK INTO FRAGMENTS ]-------------------------------

SPLIT:
; ENTRY	(Y)=INDEX OF OBJECT BEING SPLIT
; (X)=INDEX OF SHIP, SAUCER OR TORPEDO
L6F7E:  STX TEMP3               ;SAVE X
L6F80:  LDA #$50
L6F82:  STA RTIMER              ;RESET TIMER IF ROCK HAS BEEN HIT

SPLIT_1:
L6F85:  LDA OBJ,Y
L6F88:  AND #$78                ;SAVE PICTURE
L6F8A:  ASL A
L6F8B:  BPL SPLIT_2
L6F8D:  JMP SPLTTP              ;($4800)

SPLIT_2:
L6F90:  LSR A
L6F91:  STA $0F
L6F93:  LDA OBJ,Y
L6F96:  AND #$07
L6F98:  LSR A
L6F99:  TAX
L6F9A:  BEQ SPLIT_10            ;EMPTY NOW
L6F9C:  ORA $0F

SPLIT_10:
L6F9E:  STA OBJ,Y               ;NEW PICTURE & SIZE
L6FA1:  LDA NPLAYR
L6FA3:  BEQ SPLIT_20            ;WE ARE IN ATTRACT
L6FA5:  LDA TEMP3
L6FA7:  BEQ SPLIT_15            ;SHIP DOES IT
L6FA9:  CMP #$04
L6FAB:  BCC SPLIT_20            ;NO POINTS IF SAUCER DOES IT

SPLIT_15:
L6FAD:  LDA HITSCR,X            ;SCORE FOR HIT
L6FB0:  CLC
L6FB1:  JSR POINTS              ;($6C60) ADD POINTS AND CHECK FOR 10K

SPLIT_20:
L6FB4:  LDX OBJ,Y
L6FB7:  BEQ SPLIT_90            ;DISAPPEARED
L6FB9:  JSR SEARCH              ;($6D6C) SEARCH FOR NEW ENTRY
L6FBC:  BMI SPLIT_90            ;NO MORE ENTRIES
L6FBE:  INC NROCKS
L6FC1:  JSR CPYPOS              ;($6210) COPY POSITION FOR NEW ENTRY
L6FC4:  JSR NEWVEL              ;($6A57) NEW VELOCITY
L6FC7:  LDA XINC,X
L6FCA:  AND #$1F
L6FCC:  ASL A
L6FCD:  EOR OBJXL,X
L6FD0:  STA OBJXL,X             ;PREVENT OVERLAPING ROCKS
L6FD3:  JSR SEARC1              ;($6D6E) LOOK FOR NEW ENTRY
L6FD6:  BMI SPLIT_90            ;NO MORE ROOM
L6FD8:  INC NROCKS
L6FDB:  JSR CPYPOS              ;($6210) COPY POSITION & PICTURE + VELOCITY
L6FDE:  JSR NEWVEL              ;($6A57) NEW VELOCITY USING OLD
L6FE1:  LDA YINC,X
L6FE4:  AND #$1F
L6FE6:  ASL A
L6FE7:  EOR OBJYL,X
L6FEA:  STA OBJYL,X

SPLIT_90:
L6FED:  LDX TEMP3
L6FEF:  RTS

;--------------------------------[ UPDATE-UPDATE HIGH SCORE TABLE ]---------------------------------

UPDATE:
; [note] Update the high-score table with a finished game's score
L6FF0:  LDA NPLAYR
L6FF2:  BPL UPDATE_90           ;FRAME AFTER END OF GAME (A=-1)
L6FF4:  STA $77                 ;PUT UP HIGH SCORE TABLE NEXT
L6FF6:  STA UPDFLG
L6FF8:  STA $43                 ;CLEAR FLAGS
L6FFA:  STA EAHSX
L6FFC:  JSR INISOU              ;($784F) RESET SOUNDS
L6FFF:  LDX #$03                ;PLAYER SCORE INDEX

UPDATE_18:
L7001:  LDY #$00                ;INDEX INTO HIGH SCORE TABLE

UPDATE_20:
L7003:  LDA a:HSCORE,Y
L7006:  CMP SCORE,X             ;SETS CARRY
L7008:  LDA a:$0024,Y
L700B:  SBC $63,X
L700D:  LDA a:$0025,Y
L7010:  SBC $64,X
L7012:  BCC UPDATE_30           ;NEW HIGH SCORE

UPDATE_25:
L7014:  INY
L7015:  INY
L7016:  INY
L7017:  CPY #$1E
L7019:  BCC UPDATE_20           ;LOOP FOR 10 ENTRIES

UPDATE_28:
L701B:  DEX
L701C:  DEX
L701D:  DEX
L701E:  BPL UPDATE_18           ;NEXT PLAYER
L7020:  LDA $43
L7022:  BMI UPDATE_29           ;NO PLAYER 2 HIGH SCORE
L7024:  CMP UPDFLG
L7026:  BCC UPDATE_29           ;IF PLAYER 2 SCORE IS BETTER THAN PLAYER 1
L7028:  ADC #$02                ;ADD 3
L702A:  CMP #$1E
L702C:  BCC UPDATE_27           ;IF NOT OUT OF TABLE NOW
L702E:  LDA #$FF

UPDATE_27:
L7030:  STA $43                 ;NEW INDEX

UPDATE_29:
L7032:  LDX EAHSX               ;ON THE HIGH SCORE TABLE?
L7034:  BMI UPDATE_99           ;NO
L7036:  LDY #$4F                ;NOISE
L7038:  JSR SNDON               ;($775B)
L703B:  LDA CRMERR              ;COPYRIGHT ERROR?
L703D:  BEQ UPDATE_97           ;NOPE
L703F:  LDA #$55                ;1 OUT OF 3 TIMES
L7041:  CMP RANDOM              ;GIVE THE GUY 2
L7044:  BCC UPDATE_97
L7046:  INC CRDT                ;FREE GAMES
L7048:  INC CRDT

UPDATE_97:
L704A:  TXA
L704B:  BNE UPDATE_99
L704D:  SEC
L704E:  ROR CPMTST
L7050:  JSR VGRCPT              ;($77F5) TEST
L7053:  LSR CPMTST

UPDATE_99:
L7055:  LDA #$00
L7057:  STA NPLAYR              ;FLAG DONE WITH UPDATE
L7059:  STA UPDINT              ;STARTING WITH FIRST INITIAL

UPDATE_90:
L705B:  RTS

UPDATE_30:
L705C:  STX TEMP2               ;SAVE INDEX
L705E:  TXA
L705F:  LSR A
L7060:  TAX                     ;0 OR 1
L7061:  STY UPDFLG,X            ;FLAG TO GET PLAYERS INITIALS
L7063:  STY R0                  ;SAVE IT HERE TOO
L7065:  CPY EAHSX               ;KEEP LOWER OF 2
L7067:  BCS UPDATE_31           ;NOT LOWER
L7069:  STY EAHSX
L706B:  LDA #$00                ;CLEAR R1
L706D:  STA R1
L706F:  TYA                     ;GET ENTRY INDEX

UPDATE_33:
L7070:  SEC                     ;DIVIDE BY 3
L7071:  SBC #$03
L7073:  BCC UPDATE_32
L7075:  INC R1
L7077:  BNE UPDATE_33           ;(ALWAYS)

UPDATE_32:
L7079:  LDA R1                  ;GET QUO
L707B:  EOR #$FF                ;NEGATE IT
L707D:  ADC #$04                ;A=[3-(ENTRY/3)]*7
L707F:  STA R1
L7081:  ASL R1
L7083:  ADC R1
L7085:  ASL R1
L7087:  ADC R1
L7089:  STA EABC                ;KEEP BYTE COUNT
L708B:  LDA #$14                ;START @ END
L708D:  STA EAX

UPDATE_31:
L708F:  LDX #$1B

UPDATE_40:
L7091:  CPX R0
L7093:  BEQ UPDATE_45           ;IF END OF COPY
L7095:  LDA UPDINT,X            ;COPY INITIALS DOWN
L7097:  STA INITL,X
L7099:  LDA UPDFLG,X
L709B:  STA $45,X
L709D:  LDA $43,X
L709F:  STA $46,X
L70A1:  LDA PLAYR3,X            ;COPY SCORES DOWN
L70A3:  STA HSCORE,X
L70A5:  LDA LPLAYR,X
L70A7:  STA $24,X
L70A9:  LDA NPLAYR,X
L70AB:  STA $25,X
L70AD:  DEX
L70AE:  DEX
L70AF:  DEX
L70B0:  BNE UPDATE_40           ;LOOP UNTIL X=0 OR DONE

UPDATE_45:
L70B2:  LDA #$0B
L70B4:  STA INITL,X             ;START LETTERS AT A
L70B6:  LDA #$00                ;CLEARS SECOND AND THIRD INITIALS
L70B8:  STA $45,X
L70BA:  STA $46,X
L70BC:  LDA #$F0                ;1 MINUTE AT 60HZ
L70BE:  STA $77                 ;PREPARE TO TIMEOUT GETTING INITIALS
L70C0:  LDX TEMP2               ;LOOP FOR NEXT PLAYER
L70C2:  LDA $64,X
L70C4:  STA a:$0025,Y
L70C7:  LDA $63,X
L70C9:  STA a:$0024,Y
L70CC:  LDA SCORE,X
L70CE:  STA a:HSCORE,Y
L70D1:  JMP UPDATE_28           ;($701B)

ATAN:
; ENTRY	(X)=X PART OF ARCTAN (Y/X) (SIGNED NUMBER)
; (Y)=Y PART (SIGNED NUMBER)
; EXIT	(A)=ARCTAN RESULT (0 TO FF, 40=90 DEGREES)
; USES	A,X,Y,(TEMP2,TEMP2+1)
L70D4:  TYA
L70D5:  BPL ATAN1               ;IF Y>-0
L70D7:  JSR COMP                ;($70EC) +Y=-Y
L70DA:  JSR ATAN1               ;($70E0) ATAN (-Y/X)
L70DD:  JMP COMP                ;($70EC) ARCTAN(Y/X)=-ARCTAN(-Y/X)

ATAN1:
; [note] ATAN, right half-plane
L70E0:  TAY                     ;DIVISOR
L70E1:  TXA
L70E2:  BPL ATAN2               ;IF X=-0
L70E4:  JSR COMP                ;($70EC) X=-X
L70E7:  JSR ATAN2               ;($70F2) ATAN(Y/-X)
L70EA:  EOR #$80                ;ARCTAN(Y/X)=80-ARTCAN(Y/-X)

COMP:
; ENTRY	(A)=VALUE TO BE COMPLEMENTED
; EXIT	(A)=ANSWER
; USES	A
L70EC:  EOR #$FF
L70EE:  CLC
L70EF:  ADC #$01
L70F1:  RTS

ATAN2:
; [note] ATAN, first quadrant
L70F2:  STA $0D                 ;DIVISOR (X)
L70F4:  TYA                     ;DIVIDEND (Y)
L70F5:  CMP $0D
L70F7:  BCC ATAN3               ;IF Y<X USE ARCTAN ON 45 DEGREE SECTOR
L70F9:  LDY $0D                 ;ELSE USE ARCCOT
L70FB:  STA $0D
L70FD:  TYA
L70FE:  JSR ATAN3               ;($7107) ARCTAN (X/Y)
L7101:  SEC
L7102:  SBC #$40
L7104:  JMP COMP                ;($70EC) ARCTAN (Y/X)=40-ARCTAN(X/Y)

ATAN3:
; [note] ATAN, first octant: table lookup on the quotient
L7107:  JSR DIVIDE              ;($7121) 4 BIT DIVIDE
L710A:  TAX
L710B:  LDA ATANA,X             ;TABLE LOOKUP
L710E:  RTS

ATANA:
L710F:  .byte $00, $02, $05, $07, $0A, $0C, $0F, $11 ;........
L7117:  .byte $13, $15, $17, $19, $1A, $1C, $1D, $1F ;........
L711F:  .byte $20               ; 

