;------------------------------------[ DIVIDE/SIN/COS ROUTINES ]------------------------------------

DIVIDE:
; [note] 5-bit unsigned quotient of A / TEMP2+1
L7121:  LDY #$04                ;5 BITS OF QUOTIENT

DIVIDE_10:
L7123:  CMP $0D                 ;DIVISOR BIGGER?
L7125:  BCC DIVIDE_20           ;YES
L7127:  SBC $0D                 ;NO. TAKE 1 (LEAVES C=1)

DIVIDE_20:
L7129:  ROL TEMP2               ;SAVE QUOTIENT BIT
L712B:  ASL A                   ;MOVE DIVIDEND
L712C:  DEY                     ;COUNT
L712D:  BPL DIVIDE_10           ;CONTINUE
L712F:  LDA TEMP2
L7131:  AND #$1F                ;5 BITS OF RESULTS
L7133:  RTS

COS:
; COS-COSINE
; ENTRY	=ANGLE (0 TO FF)
; EXIT	(A)=COSINE(-127,127)
L7134:  CLC                     ;COS(A)=SIN(A+PI/2)
L7135:  ADC #$40

SIN:
; ENTRY	(A)=ANGLE (0 TO FF REPRESENTS 0 TO 360 DEGREES)
; (CC)=MINUS/PLUS FLAG SET CORRECTLY
; EXIT	(A)=SINE (-127 TO +127)
; USES	A,X
L7137:  BPL SIN1                ;IF PI > ANGLE >-0
L7139:  AND #$7F
L713B:  JSR SIN1                ;($7141) SIN(A) WHEN PI > A >= 0
L713E:  JMP COMP                ;($70EC) SIN(PI+A)=-SIN(A)

SIN1:
; [note] SIN for 0..180 degrees via the quarter-wave table
L7141:  CMP #$41
L7143:  BCC SIN1_10             ;PI/2 >- ANGLE >- 0
L7145:  EOR #$7F                ;SIN(PI/2+A)=SIN(PI/2-A)
L7147:  ADC #$00                ;ADD 1

SIN1_10:
L7149:  TAX
L714A:  LDA SINCOS,X
L714D:  RTS

