L715B:  LDA #$47                ;POINT TO VG RAM
L715D:  STA $04
L715F:  LDA #$02
L7161:  STA VGLIST
L7163:  LDA #$C1
L7165:  JSR VGADD2              ;($7CCC) STUFF IT
L7168:  LDA #$03
L716A:  STA TEMP1
L716C:  LDA #$76
L716E:  STA $0A
L7170:  LDA #$00
L7172:  STA VGSIZE
L7174:  LDA #$70
L7176:  LDX #$20
L7178:  JSR CM                  ;($71B5) UNPACK ATARI, INC
L717B:  JMP VGRTSL              ;($79E8) FOLLOW WITH A RTSL

