L718B:  STX TEMP1
L718D:  BNE ASTMSG_2            ;(ALWAYS) GO UNPACK MESSAGE

;---------------------------[ VGMSG-VECTOR GENERATOR MESSAGE PROCESSOR ]----------------------------

VGMSG:
; ENTRY	(Y)=MESSAGE NUMBER (0,1,2,...)
; USES	A,X,Y(TEMP1,TEMP1+1),TEMP2,(VGLIST,VGLIST+1)
; [note] Display message Y in the language the option switch selects
;        (OPTN4 bits 0-1: 0 English, 1 German, 2 French, 3 Spanish), in
;        medium characters.  Falls into VGME.
L718F:  LDA OPTN4
L7192:  AND #$03
L7194:  LDX #$10                ;MEDIUM SIZED CHARACTERS
L7196:  STX VGSIZE

VGME:
; [note] Display message Y in language A.  VGMSG arrives here with the
;        switch's language; SETROL's copyright line enters here with A=0
;        (English only).  Fetch the language block's address from VGMSGT,
;        add that block's offset for message Y, and TEMP1 now points at
;        the packed text.
L7198:  ASL A                   ;(SPECIAL ENGLISH ONLY ENTRY POINT)
L7199:  TAX                     ;2*LANGUAGE (0,2,4,OR 6)
L719A:  LDA VGMSGT+1,X
L719D:  STA $0A
L719F:  LDA VGMSGT,X            ;CARRY IS CLEAR FROM ASL ABOVE
L71A2:  STA TEMP1               ;TEMP1 SETUP NOW
L71A4:  ADC (TEMP1),Y           ;RELATIVE ADDRESS TO START OF MESSAGE
L71A6:  STA TEMP1
L71A8:  BCC VGME_10             ;NO OVERFLOW
L71AA:  INC $0A

VGME_10:
; [note] The message's screen position: VGMSGS holds an X,Y pair per
;        message number, in beam units over 4 as VGSABS takes them.
;        A = X, X = Y, then fall into CM.
L71AC:  TYA
L71AD:  ASL A
L71AE:  TAY
L71AF:  LDA VGMSGS,Y
L71B2:  LDX VGMSGS+1,Y

CM:
; [note] Position the beam at (A,X), emit a WAIT so it settles, then
;        unpack the text at TEMP1 into the display list (falls into ASTMSG).
L71B5:  JSR VGSABS              ;($7A31) POSITION BEAM
L71B8:  LDA #$70
L71BA:  JSR VGWAIT              ;($7AFC) WAIT FOR BEAM IS

ASTMSG_2:
; [note] Unpack ASCIN-packed text into the display list.  Every two bytes
;        hold three 5-bit character codes: b0 = c1<<3 | c2>>2, and
;        b1 = (c2 & 3)<<6 | c3<<1 | end.  Each code goes to VGMSG1/VGMSG2,
;        which append the glyph's JSRL word.  Stops at the end bit, or
;        early on a code of 0.
L71BD:  LDY #$00                ;Y IS INDEX FOR VGLIST
L71BF:  LDX #$00                ;X IS INDEX FOR TEMP1

ASTMSG_20:
; [note] The loop, one byte pair per pass: code 1 is the top five bits of
;        the first byte; code 2 straddles the two bytes, assembled by the
;        rotate chain; code 3 is bits 5-1 of the second byte, whose bit 0
;        ends the message.
L71C1:  LDA (TEMP1,X)
L71C3:  STA TEMP2
L71C5:  LSR A
L71C6:  LSR A                   ;2*INDEX
L71C7:  JSR VGMSG1              ;($71E6) PUT OUT CHARACTER AND UPDATE TEMP1
L71CA:  LDA (TEMP1,X)
L71CC:  ROL A
L71CD:  ROL TEMP2
L71CF:  ROL A
L71D0:  LDA TEMP2
L71D2:  ROL A
L71D3:  ASL A
L71D4:  JSR VGMSG2              ;($71EC) PUT OUT CHARACTER
L71D7:  LDA (TEMP1,X)
L71D9:  STA TEMP2
L71DB:  JSR VGMSG1              ;($71E6) PUT OUT CHARACTER AND UPDATE TEMP1
L71DE:  LSR TEMP2
L71E0:  BCC ASTMSG_20           ;NOT END OF LIST

VGMSG0:
; [note] Message done: Y counts the bytes written, VGADD moves VGLIST
;        past them.
L71E2:  DEY
L71E3:  JMP VGADD               ;($7A67) UPDATE VGLIST POINTER

VGMSG1:
; [note] Step the text pointer TEMP1 (carry into the high byte), then
;        emit the character in A - A is already the code doubled.
L71E6:  INC TEMP1               ;UPDATE INDIRECT POINTER TO CHARACTERS
L71E8:  BNE VGMSG2              ;NO OVERFLOW
L71EA:  INC $0A

VGMSG2:
; [note] Emit one character; A = code*2.  Zero ends the message: the two
;        PLAs drop VGMSG1's return address so the BNE lands in VGMSG0.
;        Codes 1-4 are blank, 0, 1, 2; any other code has 14 added so it
;        indexes A..Z in the VGMSGA JSRL table at $56F8.  In copyright-test
;        mode (CPMTST set) the bytes are checked by CPR.UP, not written.
L71EC:  AND #$3E
L71EE:  BNE VGMSG2_5            ;NOT END OF LIST
L71F0:  PLA
L71F1:  PLA                     ;PURGE RTS
L71F2:  BNE VGMSG0              ;RETURN

VGMSG2_5:
; [note] Not the end: map the code to its VGMSGA table index (see VGMSG2).
L71F4:  CMP #$0A
L71F6:  BCC VGMSG2_10           ;IF BLANK, 0,1 OR 2
L71F8:  ADC #$0D                ;SET CORRECT INDEX

VGMSG2_10:
; [note] Fetch the glyph's JSRL word from VGMSGA ($56F6+X, X = 2*code or
;        2*code+14) and store both bytes at VGLIST,Y - unless CPMTST says
;        to test them instead.
L71FA:  TAX
L71FB:  LDA L56F6,X             ;10. FOR A, 12. FOR B, ....
L71FE:  BIT CPMTST              ;TEST MODE?
L7200:  BMI VGMSG2_12           ;YEP. GO TEST IT
L7202:  STA (VGLIST),Y          ;PUT JSRL INTO VECTOR LIST
L7204:  INY
L7205:  LDA L56F7,X
L7208:  STA (VGLIST),Y
L720A:  INY

VGMSG2_13:
