DASOUN:
; [note] PNTRS: 12 sounds x 8 bytes, one per POKEY register ($2C00+n; even
;        n is a channel's frequency AUDF, odd its volume/distortion AUDC).
;        Each byte is that register's envelope offset from SOUND; 0 leaves
;        the register alone.  The sound number the game loads into Y is
;        the entry's offset + 7 (SND.T1 = $07, SND.T2 = $0F, ...).  Decoded
;        row by row (sndtab.py).
L760D:  .byte $00, $00, $00, $00, $00, $00, $01, $08 ;SND.T1 ($07) thump 1: AUDF4=T16+$01, AUDC4=T17+$08
L7615:  .byte $00, $00, $00, $00, $00, $00, $0F, $08 ;SND.T2 ($0F) thump 2: AUDF4=T26+$0F, AUDC4=T17+$08
L761D:  .byte $00, $00, $00, $00, $16, $21, $00, $00 ;SND.LS ($17) little saucer: AUDF3=LS4+$16, AUDC3=LS5+$21
L7625:  .byte $00, $00, $2F, $36, $00, $00, $00, $00 ;SND.SF ($1F) saucer fire: AUDF2=SF2+$2F, AUDC2=SF3+$36
L762D:  .byte $3D, $44, $00, $00, $00, $00, $00, $00 ;SND.PF ($27) ship fire: AUDF1=PF0+$3D, AUDC1=PF1+$44
L7635:  .byte $00, $00, $00, $00, $00, $00, $4B, $52 ;SND.EL ($2F) extra life: AUDF4=EL6+$4B, AUDC4=EL7+$52
L763D:  .byte $00, $00, $00, $00, $28, $21, $00, $00 ;SND.BS ($37) big saucer: AUDF3=BS4+$28, AUDC3=LS5+$21
L7645:  .byte $00, $00, $5D, $64, $00, $00, $00, $00 ;SND.DI ($3F) diamond zapped: AUDF2=DI2+$5D, AUDC2=DI3+$64
L764D:  .byte $00, $00, $00, $00, $6F, $7A, $85, $7A ;SND.BL ($47) ship back to life: AUDF3=BL4+$6F, AUDC3=BL5+$7A, AUDF4=BL6+$85, AUDC4=BL5+$7A
L7655:  .byte $90, $A5, $00, $00, $00, $00, $90, $B6 ;SND.HT ($4F) on the high score table: AUDF1=HT0+$90, AUDC1=HT1+$A5, AUDF4=HT0+$90, AUDC4=HT7+$B6
