SOUND:
; [note] The envelopes.  A sequence is a macro count (1-127; 127 repeats
;        for as long as the sound is allowed to run) then 4-byte steps
;        FCNT,START,CHNG,TOT - every FCNT NMIs add CHNG, TOT times, from
;        START - a 0 ending the repeated group, and 0,0 ending the
;        sequence (the source's REP / STB / SEND / MEND).  CSOUND reads
;        SOUND..SOUND+3,Y.  Decoded row by row (sndtab.py); every step
;        checked against DASOUN.MAC.
L766D:  .byte $00, $01, $04, $E0, $03, $05 ;SOUND: offset 0, a register with POINT 0 is free
L7673:  .byte $00, $00          ;end of T16
L7675:  .byte $01               ;T17: repeat 1
L7676:  .byte $04, $A8, $FF, $05 ;every 4 NMIs add -1, 5 times, from $A8
L767A:  .byte $00, $00          ;end of T17
L767C:  .byte $01               ;T26: repeat 1
L767D:  .byte $04, $D0, $03, $05 ;every 4 NMIs add 3, 5 times, from $D0
L7681:  .byte $00, $00          ;end of T26
L7683:  .byte $7F               ;LS4: repeat 127 (for the whole sound)
L7684:  .byte $01, $04, $01, $10 ;every 1 NMI add 1, 16 times, from $04
L7688:  .byte $01, $14, $FF, $10 ;every 1 NMI add -1, 16 times, from $14
L768C:  .byte $00, $00          ;end of LS4
L768E:  .byte $7F               ;LS5: repeat 127 (for the whole sound)
L768F:  .byte $20, $A2, $00, $01 ;every 32 NMIs add 0, 1 time, from $A2
L7693:  .byte $00, $00          ;end of LS5
L7695:  .byte $7F               ;BS4: repeat 127 (for the whole sound)
L7696:  .byte $01, $10, $01, $20 ;every 1 NMI add 1, 32 times, from $10
L769A:  .byte $00, $00          ;end of BS4
L769C:  .byte $01               ;SF2: repeat 1
L769D:  .byte $02, $0C, $01, $18 ;every 2 NMIs add 1, 24 times, from $0C
L76A1:  .byte $00, $00          ;end of SF2
L76A3:  .byte $01               ;SF3: repeat 1
L76A4:  .byte $10, $A4, $FF, $03 ;every 16 NMIs add -1, 3 times, from $A4
L76A8:  .byte $00, $00          ;end of SF3
L76AA:  .byte $01               ;PF0: repeat 1
L76AB:  .byte $01, $04, $01, $40 ;every 1 NMI add 1, 64 times, from $04
L76AF:  .byte $00, $00          ;end of PF0
L76B1:  .byte $01               ;PF1: repeat 1
L76B2:  .byte $10, $A4, $FF, $04 ;every 16 NMIs add -1, 4 times, from $A4
L76B6:  .byte $00, $00          ;end of PF1
L76B8:  .byte $01               ;EL6: repeat 1
L76B9:  .byte $F0, $06, $00, $02 ;every 240 NMIs add 0, 2 times, from $06
L76BD:  .byte $00, $00          ;end of EL6
L76BF:  .byte $0F               ;EL7: repeat 15
L76C0:  .byte $10, $A8, $00, $01 ;every 16 NMIs add 0, 1 time, from $A8
L76C4:  .byte $10, $A0, $00, $01 ;every 16 NMIs add 0, 1 time, from $A0
L76C8:  .byte $00, $00          ;end of EL7
L76CA:  .byte $01               ;DI2: repeat 1
L76CB:  .byte $02, $50, $01, $70 ;every 2 NMIs add 1, 112 times, from $50
L76CF:  .byte $00, $00          ;end of DI2
L76D1:  .byte $07               ;DI3: repeat 7
L76D2:  .byte $10, $A8, $00, $01 ;every 16 NMIs add 0, 1 time, from $A8
L76D6:  .byte $10, $A0, $00, $01 ;every 16 NMIs add 0, 1 time, from $A0
L76DA:  .byte $00, $00          ;end of DI3
L76DC:  .byte $0C               ;BL4: repeat 12
L76DD:  .byte $02, $0A, $01, $03 ;every 2 NMIs add 1, 3 times, from $0A
L76E1:  .byte $04, $0C, $FF, $02 ;every 4 NMIs add -1, 2 times, from $0C
