L76E7:  .byte $01               ;BL5: repeat 1
L76E8:  .byte $18, $A0, $01, $05 ;every 24 NMIs add 1, 5 times, from $A0
L76EC:  .byte $18, $A5, $FF, $05 ;every 24 NMIs add -1, 5 times, from $A5
L76F0:  .byte $00, $00          ;end of BL5
L76F2:  .byte $18               ;BL6: repeat 24
L76F3:  .byte $02, $0A, $01, $02 ;every 2 NMIs add 1, 2 times, from $0A
L76F7:  .byte $02, $0B, $00, $02 ;every 2 NMIs add 0, 2 times, from $0B
