L7719:  .byte $80, $84, $01, $04 ;every 128 NMIs add 1, 4 times, from $84
L771D:  .byte $30, $85, $FF, $04 ;every 48 NMIs add -1, 4 times, from $85
L7721:  .byte $00, $00          ;end of HT1
L7723:  .byte $04               ;HT7: repeat 4
L7724:  .byte $18, $A5, $FF, $04 ;every 24 NMIs add -1, 4 times, from $A5
L7728:  .byte $18, $A1, $01, $04 ;every 24 NMIs add 1, 4 times, from $A1
L772C:  .byte $00, $00          ;end of HT7
L772E:  .byte $10               ;DS6: repeat 16
L772F:  .byte $0C, $49, $00, $01 ;every 12 NMIs add 0, 1 time, from $49
L7733:  .byte $0C, $30, $00, $01 ;every 12 NMIs add 0, 1 time, from $30
L7737:  .byte $00, $00          ;end of DS6
L7739:  .byte $02               ;DS7: repeat 2
L773A:  .byte $C0, $A4, $00, $01 ;every 192 NMIs add 0, 1 time, from $A4
L773E:  .byte $00, $00          ;end of DS7
L7740:  .byte $01               ;S0: repeat 1
