;-----------------------------------------[ SOUND STARTER ]-----------------------------------------

SNDOFF:
; [note] Silence sound Y
L7752:  BIT SNDOO_1             ;SEV (1$=RTS=60)
L7755:  CLC                     ;(THIS MAKES IT EASY LATER)
L7756:  BCC SNDOO_4             ;(ALWAYS)

SNDPON:
; [note] Start sound Y, but only on idle channels
L7758:  SEC                     ;TURN ON SOUND WITH PRIORITY
L7759:  BCS SNDOO               ;(ALWAYS)

SNDON:
; [note] Start sound Y, taking its channels over
L775B:  CLC                     ;TURN ON SOUND

SNDOO:
; [note] SNDON/SNDPON's shared body; C = priority
L775C:  LDA NPLAYR              ;ATTRACT MODE?
L775E:  BEQ SNDOFF              ;YEP. TURN SOUNDS OFF INSTEAD
L7760:  CLV                     ;BE SURE THE V FLAG IS OFF

SNDOO_4:
; [note] Walk the eight POKEY registers, X = 7 down to 0, with Y on the
;        sound's PNTRS entry, last byte first (Y arrives as offset + 7).
L7761:  TXA                     ;SAVE X
L7762:  PHA
L7763:  LDX #$07                ;LOOP COUNTER

SNDOO_3:
; [note] Without priority (C clear) a register whose POINT is busy is left alone.
L7765:  BCC SNDOO_5             ;GO TURN IT ON
L7767:  LDA POINT,X             ;CHANNEL BUSY?
L7769:  BNE SNDOO_6             ;YEP. LEAVE IT ALONE THEN

SNDOO_5:
; [note] This register's sequence offset from PNTRS; 0 means the sound does
;        not use it.  V set (SNDOFF) substitutes 0.
L776B:  LDA DASOUN,Y            ;GET OFFSET
L776E:  BEQ SNDOO_6             ;NONE. LEAVE CHANNEL
L7770:  BVC SNDOO_7             ;NOT TO TURN OFF SOUND
L7772:  LDA #$00                ;TURN SOUND OFF

SNDOO_7:
; [note] Hand the register to CSOUND in the order the running NMI needs:
;        POINT = 0 stops whatever was playing, MCOUNT = $80 flags a start,
;        then POINT = the offset.  CSOUND takes it from there.
L7774:  PHA                     ;NMI'S ARE RUNNING SO WE HAVE TO DO THE TURN ON
L7775:  LDA #$00                ;IN A SPECIFIC ORDER. FIRST WE TURN OFF ANY
L7777:  STA POINT,X             ;SOUNDS BY ZAPPING POINT. THEN WE SET 'MCOUNT'
L7779:  LDA #$80                ;TO '80' TO SIGNAL CSOUND TO START A SOUND.
L777B:  STA MCOUNT,X            ;'MCOUNT' IS NOT DISTURBED UNLESS POINT IS
L777D:  PLA                     ;NOT ZERO. LASTLY WE SET POINT TO THE
L777E:  STA POINT,X             ;REQUIRED OFFSET. CSOUND TAKES OVER

SNDOO_6:
; FROM HERE
; [note] Next register.
L7780:  DEY                     ;COUNT
L7781:  DEX                     ;COUNT
L7782:  BPL SNDOO_3             ;CONTINUE
L7784:  PLA                     ;RESTORE X AND EXIT
L7785:  TAX

SNDOO_1:
; [note] Shared return; SNDOFF also BITs this $60 to set V.
L7786:  RTS

;-----------------------------------------[ SOUND ROUTINE ]-----------------------------------------

CSOUND:
; [note] Step all eight sound channels; once per NMI
L7787:  LDX #$07                ;8 ITEMS

CSOUND_4:
; [note] Per register: idle if POINT is 0.  MCOUNT bit 7 means a sound was
;        just requested - go start it.  Otherwise count FRAMES down; at 0,
;        count COUNT down; at 0 the step is done, else CURRENT += CHNG.
L7789:  LDY POINT,X             ;ANY SOUND?
L778B:  BEQ CSOUND_6            ;NO
L778D:  LDA MCOUNT,X            ;ARE WE TO START ONE?
L778F:  BMI CSOUND_11           ;YES. GO START IT
L7791:  DEC FRAMES,X            ;COUNT DOWN TIMER
L7793:  BNE CSOUND_1            ;CONTINUE
L7795:  DEC COUNT,X             ;COUNT DOWN TOTAL COUNTER
L7797:  BEQ CSOUND_2            ;DONE
L7799:  LDA CURRENT,X           ;CHANGE SOUND
L779B:  CLC
L779C:  ADC SOUND+2,Y           ;BY ADDING CHANGE CODE
L779F:  JMP CSOUND_5            ;($77B0)

CSOUND_2:
; [note] Step done: Y += 4 to the next STB group.
L77A2:  INY                     ;Y=Y+4
L77A3:  INY
L77A4:  INY
L77A5:  INY

CSOUND_7:
; [note] Load a step: POINT = Y, COUNT = TOT (SOUND+3,Y), CURRENT = START
;        (SOUND+1,Y).
L77A6:  STY POINT,X
L77A8:  LDA SOUND+3,Y
L77AB:  STA COUNT,X             ;RESET TOTAL COUNTER
L77AD:  LDA SOUND+1,Y

CSOUND_5:
; [note] Store the value, reload FRAMES = FCNT (SOUND,Y).  FCNT 0 is the
;        group terminator: rewind Y to MPNTR and repeat while MCOUNT lasts,
;        else step past the 0 to the next macro count (CSOUND_11).
L77B0:  STA CURRENT,X           ;RESET VALUE
L77B2:  LDA SOUND,Y
L77B5:  STA FRAMES,X            ;RESET TIMER
L77B7:  BNE CSOUND_1            ;CONTINUE
L77B9:  LDY MPNTR,X             ;SET UP Y IN CASE OF RESTART
L77BB:  DEC MCOUNT,X            ;MACRO COUNT
L77BD:  BNE CSOUND_7            ;RESTART
L77BF:  LDY POINT,X
L77C1:  INY                     ;SKIP OVER TERM
L77C2:  BNE CSOUND_11           ;(ALWAYS)

CSOUND_10:
; [note] Macro count 0: the sound is over.  Y = 0 goes into POINT and CURRENT.
L77C4:  TAY                     ;THIS MAKES AN EASY EXIT

CSOUND_8:
; [note] Free the register (POINT = 0).
L77C5:  STY POINT,X             ;ZAP THE POINTER

CSOUND_6:
; [note] Silence it (CURRENT = 0), then write it out.
L77C7:  STY CURRENT,X           ;ZAP SOUND TOO

CSOUND_1:
; [note] Write CURRENT to POKEY register X; next register; exit after 0.
L77C9:  LDA CURRENT,X           ;GET SOUND
L77CB:  STA POKEY,X             ;WRITE TO POKEY
L77CE:  DEX                     ;COUNT
L77CF:  BPL CSOUND_4
L77D1:  RTS                     ;EXIT (FALL THUR TO IDCYC)

CSOUND_11:
; [note] Start, or continue with the next macro: the count at POINT; 0 ends.
L77D2:  LDA SOUND,Y             ;GET COUNT
L77D5:  BEQ CSOUND_10           ;END

CSOUND_9:
; [note] MCOUNT = the count, MPNTR = the first step (for repeats), load it.
L77D7:  STA MCOUNT,X
L77D9:  INY                     ;SKIP UP TO SOUND
L77DA:  STY MPNTR,X             ;SAVE POINTER
L77DC:  BNE CSOUND_7            ;(ALWAYS)

RADDR:
L77DE:  .byte $01, $E0, $C0, $E1 ;....

ROCKSA:
L77E2:  .byte $E5, $C3, $CA, $C3, $AF, $C3, $94, $C3 ;........

MODULO:
L77EA:  .byte $7F, $02, $04, $04, $05, $03, $7F, $7F ;........

FILL:
L77F2:  .byte $69, $15, $60     ;i.`

;----------------------------------------[ COPYRIGHT STUFF ]----------------------------------------

VGRCPT:
; also ASTMTS in the linker map
; [note] The copyright check: compare the display list against the expected bytes
L77F5:  BIT CPMTST              ;SHOULD WE TEST?
L77F7:  BPL VGRCPT_3            ;NO

VGRCPT_1:
L77F9:  LDA VGLIST              ;SAVE VGLIST
L77FB:  PHA
L77FC:  LDA $04
L77FE:  PHA
L77FF:  LDA #$47
L7801:  STA $04
L7803:  LDA #$02
L7805:  STA VGLIST
L7807:  LDX #$C9
L7809:  LDY #$00
L780B:  LDA #$C1
L780D:  JSR CPR_UP              ;($7835) FIX IT
L7810:  TXA
L7811:  JSR CPR_UP              ;($7835)
L7814:  LDX #$07

VGRCPT_2:
L7816:  LDA CPR_DT,X            ;GET LIST
L7819:  JSR CPR_UP              ;($7835) UPDATE ERROR FLAG
L781C:  DEX                     ;COUNT
L781D:  BPL VGRCPT_2
L781F:  DEY                     ;Y-1
L7820:  JSR VGADD               ;($7A67) ADD Y+1 TO VGLIST
L7823:  LDA #$45                ;SET UP TEMP1,TEMP1+1
L7825:  STA TEMP1
L7827:  LDA #$78
L7829:  STA $0A
L782B:  JSR ASTMSG_2            ;($71BD) CHECK MESSAGE
L782E:  PLA
L782F:  STA $04                 ;RESTORE VGLIST
L7831:  PLA
L7832:  STA VGLIST

VGRCPT_3:
L7834:  RTS                     ;EXIT

CPR_UP:
; [note] Fold one expected byte into the copyright error flag
L7835:  EOR (VGLIST),Y
L7837:  ORA CRMERR
L7839:  STA CRMERR
L783B:  INY
L783C:  RTS

CPR_DT:
L783D:  .byte $00, $00, $70, $00, $01, $C0, $A0, $80 ;..p.....

ASTMT:
L7845:  .byte $1F, $C4, $09, $70, $2D, $9A, $0B, $64 ;...p-..d
L784D:  .byte $38, $00          ;8.

INISOU:
; also ST1 in the linker map
; placed by hand: DASOUN.MAC:423 `INISOU:: LDA I,0 / LDX #7 / 1$: STA X,POINT / DEX / BPL 1$ / STA AUDCTL`. Linked into the DSTNMI region, away from the rest of DASOUN, so the in-module order check rejects it. ST1 is the linker map's name for the address and is kept as the alias
L784F:  LDA #$00
L7851:  LDX #$07

INISOU_1:
; placed by hand: DASOUN.MAC:425 `1$: STA X,POINT`, the clear loop
L7853:  STA POINT,X
L7855:  DEX
L7856:  BPL INISOU_1
L7858:  STA OPTN5
L785B:  RTS

;------------------------------------[ NMI - INTERRUPT ROUTINE ]------------------------------------

NMI:
; also DSTNMI in the linker map
; [note] The interrupt, every 4 ms: switches, coins, sound, POKEY
L785C:  BIT $01FF               ;POWER UP SELF-TEST?
L785F:  BPL NMI_100
L7861:  RTI

NMI_100:
L7862:  PHA                     ;SAVE MACHINE
L7863:  TYA
L7864:  PHA
L7865:  TXA
L7866:  PHA
L7867:  CLD
L7868:  LDA $01FF               ;STACK OVERFLOW
L786B:  ORA $01D0               ;STACK UNDERFLOW

NMI_2:
L786E:  BNE NMI_2               ;OOPS - STACK ERROR
L7870:  INC INTCT               ;ANOTHER INTERRUPT
L7872:  LDA INTCT
L7874:  AND #$03                ;16 MS
L7876:  BNE NMI_10
L7878:  INC SYNC                ;MAIN LINE SYNC UP (16 MS)
L787A:  LDA SYNC
L787C:  CMP #$03                ;ARE WE OK?
L787E:  BCC NMI_10              ;OK

NMI_HANG:
; placed by hand: DSTNMI.MAC:90 `BNE .  ;PROGRAM WHERE ARE YOU?`. The source branches to itself without a label; NAMED here. Reached when the main line misses two SYNC ticks, and spins until the watchdog resets the board
L7880:  BNE NMI_HANG            ;PROGRAM WHERE ARE YOU?

NMI_127:
L7882:  STA VGRESET             ;STOP VG IN CASE ITS HUNG

NMI_10:
L7885:  LDX NPLAYR
L7887:  BNE NMI_3               ;GAME TIME
L7889:  LDA UPDFLG              ;UPDATING INITIALS?
L788B:  AND $43
L788D:  BPL NMI_3               ;YEP. STILL HAVE SOUNDS
L788F:  STX $2C0F               ;RESET POKEY
L7892:  LDX #$04

NMI_11:
L7894:  DEX                     ;WASTE TIME
L7895:  BNE NMI_11
L7897:  LDX #$07
L7899:  STX $2C0F               ;REENABLE POKY
L789C:  STX $2C0B               ;START POTS
L789F:  LDA OPTN5               ;READ OPTION SWITCH
L78A2:  EOR #$FF
L78A4:  STA CMODE               ;KEEP THEM

NMI_3:
L78A6:  JSR CSOUND              ;($7787) DO SOUNDS

;------------------------------------------[ DETECT COIN ]------------------------------------------

MOOLAH:
; INSTRUCTIONS IN BRACKETS( "[" AND "]" ) ARE FOR ILLUSTRATION ONLY, AND ARE NOT
; ACTUALLY ASSEMBLED.
L78A9:  LDX #$02                ;X IS USED TO INDEX FROM RIGHT TO LEFT COIN MECH

DETCT:
; [note] Debounce one coin mech
L78AB:  LDA COINA,X
L78AE:  ASL A
L78AF:  LDA CNSTT,X
L78B1:  AND #$1F                ;SHARED INST. SEE BELOW IN BRACKETS []
L78B3:  BCC DETCT_5             ;BRANCH IF INPUT LOW (COIN ABSENT)
L78B5:  BEQ DETCT_1             ;STICK AT 0 (TERMINAL COUNT)
L78B7:  CMP #$1B                ;IN FIRST FIVE SAMPLES?
L78B9:  BCS DETCT_10            ;YES, RUN FAST
L78BB:  TAY                     ;ELSE SAVE STATUS
L78BC:  LDA INTCT               ;CHECK INTERUPT CTR
L78BE:  AND #$07                ;ARE D0-D2 ALL ONES?
L78C0:  CMP #$07                ;SET CARRY IF SO
L78C2:  TYA                     ;STATUS BACK INTO ACC
L78C3:  BCC DETCT_1             ;SKIP IF NOT ALL ONES

DETCT_10:
; [AND I,31.]             ISOLATE COIN-ON DOWN-COUNTER, RESET COIN-OFF UP-CTR.
L78C5:  SBC #$01                ;CARRY SET

DETCT_1:
L78C7:  STA CNSTT,X             ;SAVE UPDATED STATUS
L78C9:  LDA LAM                 ;CHECK SLAM SWITCH
L78CC:  AND #$80
L78CE:  BEQ DETCT_2             ;BRANCH IF BIT LO (SWITCH OFF)
L78D0:  LDA #$F0                ;ELSE SET PRE-COIN SLAM TIMER
L78D2:  STA LMTIM               ;DECR. 8 TIMES/FRAME=PRST FRAMES

DETCT_2:
L78D4:  LDA LMTIM               ;CHECK PRE-COIN SLAM TIMER
L78D6:  BEQ DETCT_3             ;O.K.
L78D8:  DEC LMTIM               ;ELSE RUN TIMER
L78DA:  LDA #$00
L78DC:  STA CNSTT,X             ;CLEAR COIN STATUS
L78DE:  STA PSTSL,X             ;CLEAR POST-COIN SLAM-TIMER

DETCT_3:
L78E0:  CLC                     ;DEFAULT "NO COIN DETECTED"
L78E1:  LDA PSTSL,X             ;CHECK POST-COIN SLAM-TIMER
L78E3:  BEQ DETCT_8             ;EMPTY, PROCEED
L78E5:  DEC PSTSL,X             ;RUN TIMER
L78E7:  BNE DETCT_8             ;NOT DONE, PROCEED
L78E9:  SEC                     ;WHEN IT BECOMES ZERO, INDICATE A COIN
L78EA:  BCS DETCT_8             ;(ALWAYS)

DETCT_5:
L78EC:  CMP #$1B                ;IS COIN VALID YET (ON FOR >4 SAMPLES)
L78EE:  BCS DETCT_6             ;NO, RESET IT
L78F0:  LDA CNSTT,X             ;GET STATUS AGAIN
L78F2:  ADC #$20                ;BUMP COIN-OFF UP-CTR.
L78F4:  BCC DETCT_1             ;IF IT DIDN'T WRAP, JUST STORE STATUS
L78F6:  BEQ DETCT_6             ;IT WRAPPED BUT COIN WAS ON TOO LONG, JUST RESET
L78F8:  CLC                     ;SET "VALIDITY" AGAIN

DETCT_6:
L78F9:  LDA #$1F                ;RESET DOWN-COUNTER
L78FB:  BCS DETCT_1             ;BRANCH IF COIN TOO LONG OR TOO SHORT
L78FD:  STA CNSTT,X             ;SAVE RESET STATUS
L78FF:  LDA PSTSL,X             ;CHECK HOWIES ASSUMPTION
L7901:  BEQ DETCT_7             ;BRANCH IF $PSTSL VACANT
L7903:  SEC                     ;ELSE GIVE CREDIT A LITTLE EARLY

DETCT_7:
; [CLC]                   DEFAULT TO "NO COIN" (CARRY IS ALREADY CLEAR)
L7904:  LDA #$78                ;/(4 COUNTS/FRAME)="POST" FRAMES
L7906:  STA PSTSL,X             ;DELAY ACCEPTANCE FOR POST/60 SEC.

DETCT_8:
L7908:  BCC DETCT_9
L790A:  LDA #$00                ;START WITH 0 (TO ADD 1)
L790C:  CPX #$01                ;CHECK WHICH MECH
L790E:  BCC DETCT_85            ;IF LEFT, ALWAYS ADD 1
L7910:  BEQ DETCT_83            ;IF CENTER, CHECK HALF-MUL
L7912:  LDA CMODE               ;GET DOLLAR MUL
L7914:  AND #$0C
L7916:  LSR A
L7917:  LSR A
L7918:  BEQ DETCT_85            ;00-ADD 1
L791A:  ADC #$02                ;ELSE MAP 1,2,3 TO 3,4,5
L791C:  BNE DETCT_85            ;(ALWAYS)

;---------------------------------------[ MECH-MULTIPLIERS ]----------------------------------------

DETCT_83:
L791E:  LDA CMODE               ;GET COIN MODE FROM ZERO-PAGE
L7920:  AND #$10                ;ISOLATE HALF-MULTIPLIER
L7922:  BEQ DETCT_85
L7924:  LDA #$01

DETCT_85:
; ACC=0 FOR 1 "UNIT" ,<>0 FOR 2 "UNITS" PER MIDDLE-MECH COIN.
; Z FLAG SET PER ACC.  CARRY IS DON'T CARE
L7926:  SEC
L7927:  PHA
L7928:  ADC BCCNT               ;UPDATE BONUS-ADDER COUNTER
L792A:  STA BCCNT
L792C:  PLA
L792D:  SEC
L792E:  ADC CNCT
L7930:  STA CNCT
L7932:  INC CCTIM,X             ;"QUEUE" PULSE FOR E.M. COUNTER

DETCT_9:
; ###NOTE:  THIS CODE PROVIDED ONLY FOR OLD AMERICAN GAMES. USE WITH 5 DM
; MECHS IS STRONGLY DISCOURAGED
; FALL THROUGH TO BUMP $CNCT
L7934:  DEX
L7935:  BMI BONUS
L7937:  JMP DETCT               ;($78AB)

;------------------------------------------[ BONUS-ADDER ]------------------------------------------

BONUS:
; FALL THRU TO BONUS-ADDER
L793A:  LDA CMODE               ;GET BONUS ADDER MODE
L793C:  LSR A
L793D:  LSR A
L793E:  LSR A
L793F:  LSR A
L7940:  LSR A                   ;ISOLATE BONUS-ADDER MODE IN BITS 0-2
L7941:  TAY
L7942:  LDA BCCNT
L7944:  SEC
L7945:  SBC MODULO,Y            ;SEE IF ENOUGH UNIT-COINS HAVE ACCUMULATED
L7948:  BMI CNVRT               ;BRANCH IF NOT
L794A:  STA BCCNT               ;ELSE UPDATE BONUS-ADDER AND...
L794C:  INC BC                  ;GIVE ONE OR TWO BONUS UNIT-COINS
L794E:  CPY #$03
L7950:  BNE CNVRT
L7952:  INC BC                  ;MODE 3 YIELDS 2 BONUS COINS FOR 4 INSERTED

CNVRT:
; placed by hand: DCIN65.MAC:585 `$CNVRT: GCM`, coins to credits. $EXTB (DCIN65.MAC:579), the bonus adder's exit, is the same address
L7954:  LDA CMODE
L7956:  AND #$03
L7958:  TAY
L7959:  BEQ CNVRT_2
L795B:  LSR A
L795C:  ADC #$00
L795E:  EOR #$FF
L7960:  SEC
L7961:  ADC CNCT
L7963:  BCS CNVRT_33
L7965:  ADC BC
L7967:  BMI EXT
L7969:  STA BC
L796B:  LDA #$00

CNVRT_33:
; placed by hand: DCIN65.MAC:602 `33$:  ;GENERATE CREDITS: 1 OR 2`
L796D:  CPY #$02
L796F:  BCS CNVRT_1
L7971:  INC CRDT

CNVRT_1:
; placed by hand: DCIN65.MAC:606 `1$: INC $$CRDT`
L7973:  INC CRDT

CNVRT_2:
; placed by hand: DCIN65.MAC:607 `2$: STA $CNCT  ;UPDAT COINCT`
L7975:  STA CNCT

EXT:
; [note] Pulse the coin counters
L7977:  LDA INTCT               ;GET $INTCT
L7979:  LSR A                   ;USE LSB FOR PULSE=4 FRAMES
L797A:  BCS COINC
L797C:  LDY #$00                ;START WITH FLAG OF 0
L797E:  LDX #$02

;--------------------------------------[ ELECTRO-MECH. CTRS ]---------------------------------------

EXT_1:
; FALL THROUGH TO HANDLE E.M. COUNTERS
L7980:  LDA CCTIM,X             ;CHECK TIMER(X)
L7982:  BEQ EXT_3               ;NEITHER RUNNING NOR PENDING
L7984:  CMP #$10                ;IS IT RUNNING
L7986:  BCC EXT_3               ;NO, SKIP
L7988:  ADC #$EF                ;ELSE DEC 4 MSB
L798A:  INY                     ;SET ON FLAG

EXT_2:
L798B:  STA CCTIM,X

EXT_3:
L798D:  DEX
L798E:  BPL EXT_1
L7990:  TYA                     ;CHECK "ON" FLAG
L7991:  BNE COINC               ;SKIP IF ANY ON
L7993:  LDX #$02

EXT_4:
; IF NONE OF THE COUNTERS ARE CURRENTLY ON, WE CHECK TO SEE IF ANY CAN BE
; STARTED.
L7995:  LDA CCTIM,X             ;NEED WE START THIS ONE
L7997:  BEQ EXT_5               ;NO, NO COUNTS PENDING
L7999:  CLC
L799A:  ADC #$EF                ;SET 4 MSB, DEC 4 LSB
L799C:  STA CCTIM,X             ;START TIMER
L799E:  BMI COINC               ;EXIT, SO WE DON'T START MORE

EXT_5:
L79A0:  DEX
L79A1:  BPL EXT_4

COINC:
; [note] Drive the coin outputs and return from the interrupt
L79A3:  LDA CCTIM               ;LEFT MECH
L79A5:  STA CCLFT
L79A8:  LDA $98                 ;MIDDLE
L79AA:  STA CCMID
L79AD:  LDA $99
L79AF:  STA CCRIT               ;RIGHT
L79B2:  LDA CKERR               ;ANY CHECKSUM ERRORS?
L79B4:  BEQ COINC_17            ;NOPE
L79B6:  LDA HOLE                ;TIME TO ZAP THE PROGRAM?
L79B8:  BEQ COINC_17            ;NOPE
L79BA:  LDA NPLAYR              ;ATTRACT MODE?
L79BC:  BEQ COINC_17            ;YEP. DON'T DO ANYTHING
L79BE:  TSX                     ;GET THE PSB
L79BF:  LDA $0104,X
L79C2:  ORA #$08                ;SED
L79C4:  STA $0104,X

COINC_17:
