L79C9:  EOR #$03
L79CB:  ROR A
L79CC:  ROR A
L79CD:  STA SLMP1               ;LAMP 1
L79D0:  ROR A
L79D1:  STA SLMP2               ;LAMP 2
L79D4:  LDA LMTIM
