L7A40:  ASL A
L7A41:  ROL $08
L7A43:  ASL A
L7A44:  ROL $08
L7A46:  STA $07
L7A48:  LDX #$05

;------------------------------[ VGLABS - ADD LABS INTO VECTOR LIST ]-------------------------------

VGLABS:
; [note] Append a LABS from the zero-page position block
L7A4A:  LDA VGBRIT,X
L7A4C:  LDY #$00
L7A4E:  STA (VGLIST),Y          ;Y LSB
L7A50:  LDA VGLIST,X
L7A52:  AND #$0F
L7A54:  ORA #$A0
L7A56:  INY
L7A57:  STA (VGLIST),Y          ;Y MSB+OPCODE
L7A59:  LDA $00,X
L7A5B:  INY
L7A5C:  STA (VGLIST),Y          ;X LSB
L7A5E:  LDA VGSIZE,X
L7A60:  AND #$0F
L7A62:  ORA VGSIZE              ;ADD SCALE TO DETERMIN SIZE
L7A64:  INY
L7A65:  STA (VGLIST),Y          ;X MSB

;-------------------------------[ VGADD - ADD Y+1 TO VECTOR ADDRESS ]-------------------------------

VGADD:
; [note] Advance VGLIST by Y+1
L7A67:  TYA                     ;ADD 1+(Y) TO VGLIST
L7A68:  SEC
L7A69:  ADC VGLIST
L7A6B:  STA VGLIST
L7A6D:  BCC VGA_0
L7A6F:  INC $04

VGA_0:
; [note] Shared return
L7A71:  RTS

VGVCTR:
; [note] The general vector emitter (unused by the shipped ROM)
L7A72:  LDX #$00                ;INITIALISE X
L7A74:  LDA $06                 ;GET HIGH BYTE OF X
L7A76:  CMP #$80                ;SET CARRY = TO BIT 7
L7A78:  BCC VGA_0_2             ;ITS ALREADY +
L7A7A:  TXA                     ;XCOMP=0-XCOMP
L7A7B:  SBC XCOMP               ;(CARRY SET ON ENTRY)
L7A7D:  STA XCOMP
L7A7F:  TXA
L7A80:  SBC $06
L7A82:  STA $06                 ;(CARRY ALWAYS SET AFTER NEGATE OF - NUMBER)

;-------------------------------[ VGVCTR - ADD VCTR TO VECTOR LIST ]--------------------------------

VGA_0_2:
L7A84:  ROL TEMP1               ;SAVE SIGN OF X
L7A86:  LDA $08                 ;REPEAT ABOVE FOR Y
L7A88:  CMP #$80
L7A8A:  BCC VGA_0_4
L7A8C:  TXA                     ;XCOMP=0-XCOMP
L7A8D:  SBC $07
L7A8F:  STA $07
L7A91:  TXA
L7A92:  SBC $08
L7A94:  STA $08                 ;(CARRY ALWAYS SET AFTER A NEGATE

VGA_0_4:
L7A96:  ROL TEMP1               ;SAVE SIGN OF Y
L7A98:  ORA $06
L7A9A:  BEQ VGA_0_5             ;IF LESS THAN 256 IN LENGTH
L7A9C:  CMP #$02
L7A9E:  BCS VGA_0_20            ;NO NORMALIZE NEEDED
L7AA0:  LDY #$01                ;ONE SHIFT NEEDED
L7AA2:  BNE VGA_0_8             ;ALWAYS

VGA_0_5:
L7AA4:  LDY #$02
L7AA6:  LDX #$09
L7AA8:  LDA XCOMP
L7AAA:  ORA $07
L7AAC:  BEQ VGA_0_20            ;ZERO LENGTH VECTOR

VGA_0_6:
L7AAE:  BMI VGA_0_8             ;COUNT IS RIGHT

VGA_0_7:
L7AB0:  INY                     ;GET NORMALIZE COUNT
L7AB1:  ASL A
L7AB2:  BPL VGA_0_7

VGA_0_8:
L7AB4:  TYA
L7AB5:  TAX                     ;SAVE SHIFT COUNT FOR TIMER
L7AB6:  LDA $06

VGA_0_10:
L7AB8:  ASL XCOMP
L7ABA:  ROL A
L7ABB:  ASL $07
L7ABD:  ROL $08
L7ABF:  DEY
L7AC0:  BNE VGA_0_10            ;NORMALIZE NUMBERS
L7AC2:  STA $06

VGA_0_20:
L7AC4:  TXA
L7AC5:  SEC
L7AC6:  SBC #$0A
L7AC8:  EOR #$FF                ;9-COUNT=TIMER (TTTT)
L7ACA:  ASL A
L7ACB:  ROR TEMP1               ;SIGN OF Y (S)
L7ACD:  ROL A
L7ACE:  ROR TEMP1               ;SIGN OF X (S)
L7AD0:  ROL A
L7AD1:  ASL A
L7AD2:  STA TEMP1               ;TTTTXSSX
L7AD4:  LDY #$00
L7AD6:  LDA $07
L7AD8:  STA (VGLIST),Y
L7ADA:  LDA TEMP1
L7ADC:  AND #$F4                ;SIGN+EXPONENT
L7ADE:  ORA $08
L7AE0:  INY
L7AE1:  STA (VGLIST),Y
L7AE3:  LDA XCOMP
L7AE5:  INY
L7AE6:  STA (VGLIST),Y
L7AE8:  LDA TEMP1
L7AEA:  AND #$02
L7AEC:  ASL A                   ;SIGN
L7AED:  ORA VGBRIT              ;BRIGHTNESS
L7AEF:  ORA $06
L7AF1:  INY
L7AF2:  STA (VGLIST),Y          ;STORE LAST BYTE OF VCTR
L7AF4:  JMP VGADD               ;($7A67) UPDATE VECTOR ADDRESS POINTER

;---------------------------[ VGAWT - DO A VGSABS FOLLOWED BY A WAIT 7 ]----------------------------

VGAWT:
; [note] Position the beam, then a WAIT
L7AF7:  JSR VGSABS              ;($7A31) DO A LABS
L7AFA:  LDA #$70                ;FOLLOW WITH A WAIT

;-------------------------------[ VGWAIT - ADD WAIT TO VECTOR LIST ]--------------------------------

VGWAIT:
; [note] A WAIT with no intensity
L7AFC:  LDX #$00                ;NO INTENSITY

;--------------------------[ VGDOT - DRAW A DOT AT THE CURRENT POSITION ]---------------------------

VGDOT:
; [note] A dot: a WAIT with intensity X
L7AFE:  LDY #$01
L7B00:  STA (VGLIST),Y          ;SAVE TIMER VALUE
L7B02:  DEY
L7B03:  TYA                     ;(A):=(Y):=0
L7B04:  STA (VGLIST),Y          ;0, TIMER, 0, 0=WAIT
L7B06:  INY
L7B07:  INY
L7B08:  STA (VGLIST),Y
L7B0A:  INY
L7B0B:  TXA                     ;INSERT INTENSITY
L7B0C:  STA (VGLIST),Y
L7B0E:  JMP VGADD               ;($7A67)

;---------------------------------------------[ ENTRY ]---------------------------------------------

EAUPD:
; also EAROM in the linker map
; [note] One step of the EAROM state machine
L7B11:  LDA INTCT               ;CAN ONLY DO HIS ONCE EVERY 16 INTERRUPTS
L7B13:  AND #$0C
L7B15:  BNE EAUPD_1             ;WAIT
L7B17:  LDA EAFLG               ;ANY ACTIVITY?
L7B19:  BEQ EAUPD_2             ;NO. DESELECT EA ROM AND EXIT
L7B1B:  BPL EAUPD_3             ;R/W
L7B1D:  LDX EAX                 ;ERASE.GET ADDRESS
L7B1F:  LDA #$06                ;SELECT ERASE MODE
L7B21:  STA EACTL               ;DE-SELECT
L7B24:  STA EADAL,X             ;STORE ADDRESS
L7B27:  LDA #$0E
L7B29:  DEC EAX                 ;NEXT @
L7B2B:  DEC EABC                ;COUNT
L7B2D:  BNE EAUPD_2             ;CONTINUE
L7B2F:  LDX #$40                ;SELECT WRITE MODE
L7B31:  STX EAFLG

EAUPD_9:
L7B33:  INC EAX                 ;NEXT ADDRESS

EAUPD_2:
L7B35:  STA EACTL               ;DO EA CONTROL

EAUPD_1:
