EAUPD_3:
L7B39:  LDY EABC                ;GET BYTE POINTER
L7B3B:  BNE EAUPD_5             ;NO FIRST
L7B3D:  STY EACS                ;RESET CHECKSUM

EAUPD_5:
L7B3F:  ASL A                   ;MODE?(CLEARS CARRY)
L7B40:  BPL EAUPD_10            ;READ
L7B42:  LDA EABDS,Y             ;GET @ OF @
L7B45:  BPL EAUPD_6
L7B47:  STA EABC                ;RESET BYTE COUNT
L7B49:  INC EAHSX               ;UP TO NEXT
L7B4B:  INC EAHSX               ;INITIAL
L7B4D:  INC EAHSX
L7B4F:  LDA EACS                ;GET CHECKSUM
L7B51:  BCC EAUPD_7             ;(ALWAYS)

EAUPD_6:
L7B53:  ADC EAHSX               ;COMPUTE SOURCE ADDR
L7B55:  TAX
L7B56:  LDA HSCORE,X            ;ACCUMULATE CHKSUM
L7B58:  ADC EACS
L7B5A:  STA EACS
L7B5C:  LDA HSCORE,X

EAUPD_7:
L7B5E:  INC EABC
L7B60:  LDX EAX                 ;@INTO EA ROM TO PUT DATA
L7B62:  STA EADAL,X             ;SET UP ADDRESS/DATA
L7B65:  LDA #$04                ;SELECT WRITE MODE
L7B67:  STA EACTL
L7B6A:  LDA #$0C

EAUPD_4:
