L7B6F:  BCC EAUPD_9             ;NO
L7B71:  LDX #$00                ;YES. RESET ACTIVITY FLAG
L7B73:  STX EAFLG               ;DONE
L7B75:  BEQ EAUPD_2             ;(ALWAYS)

EAUPD_10:
L7B77:  LDX EAX
L7B79:  LDA #$08
L7B7B:  STA EADAL,X             ;SELECT @
L7B7E:  STA EACTL               ;SELECT READ MODE
L7B81:  LDA #$09
L7B83:  STA EACTL
L7B86:  LDA #$08
L7B88:  STA EACTL
L7B8B:  LDX #$00                ;NEED A 0 LATER
L7B8D:  LDA EABDS,Y             ;GET @ OF @
L7B90:  BPL EAUPD_11            ;NORMAL
L7B92:  STX EABC                ;RESET BYTE COUNT
L7B94:  LDA EAIN                ;READ ROM DATA
L7B97:  STX EACTL               ;DE-SELECT CHIP
L7B9A:  EOR EACS                ;MATCH CHKSUM?
L7B9C:  BEQ EAUPD_12            ;YEP
L7B9E:  LDY #$02                ;CHECKSUM ERROR. IGNORE ROM DATA, CLEAR RAM DATA
L7BA0:  TYA                     ;LDA #2
L7BA1:  ADC EAHSX               ;COMPUTE DST @
L7BA3:  TAX
L7BA4:  LDA #$00

EAUPD_13:
L7BA6:  STA HSCORE,X            ;BLANK OUT SCORE AND INITIALS
L7BA8:  STA INITL,X
L7BAA:  DEX
L7BAB:  DEY
L7BAC:  BPL EAUPD_13
L7BAE:  INC EABAD               ;SIGNAL WE GO A BAD ENTRY

EAUPD_14:
