L7D7F:  BCS STEST3              ;RAM IS GOOD

CKSUM5:
L7D81:  .byte $2C               ;,

P0123E:
; [note] RAM test: error in the first 1K
L7D82:  LDY #$00                ;ERROR IN FIRST 1K
L7D84:  BEQ STEST1

P4000E:
; [note] RAM test: error in vector RAM
L7D86:  LDY #$00
L7D88:  LDX VGSIZE
L7D8A:  CPX #$04
L7D8C:  BCC STEST1              ;IF ERROR IN FIRST 1K OF RAM
L7D8E:  INY
L7D8F:  CPX #$44
L7D91:  BCC STEST1              ;ERROR IN SECOND 1K RAM
L7D93:  INY                     ;ERROR MUST BE IN THIRD 1K RAM

STEST1:
; [note] Bad RAM: beep out the failing page on the 3 kHz clock
L7D94:  CMP #$10                ;SET TO 1,2 OR 3
L7D96:  ROL A
L7D97:  AND #$1F
L7D99:  CMP #$02
L7D9B:  ROL A                   ;EACH 1 REPRESENTS A BAD 2114
L7D9C:  AND #$03

STEST1_15:
L7D9E:  DEY
L7D9F:  BMI STEST1_20           ;IF THIS 1K BLOCK WAS BAD
L7DA1:  ASL A                   ;FLAG 2 RAM IC'S AS GOOD
L7DA2:  ASL A
L7DA3:  BCC STEST1_15           ;ALWAYS

STEST1_20:
L7DA5:  LSR A
L7DA6:  LDY #$07
L7DA8:  STY $2C0F
L7DAB:  LDX #$20                ;HIGH FREQ (IF CHIP GOOD)
L7DAD:  BCC STEST1_25           ;IF RAM IC IS GOOD
L7DAF:  LDX #$80                ;LOW FREQ

STEST1_25:
L7DB1:  STX POKEY
L7DB4:  LDX #$A8
L7DB6:  STX $2C01
L7DB9:  LDX #$00

STEST1_31:
L7DBB:  BIT THRKHZ              ;COUNT 1 3KHZ SIGNAL
L7DBE:  BPL STEST1_31

STEST1_32:
L7DC0:  BIT THRKHZ
L7DC3:  BMI STEST1_32
L7DC5:  DEX
L7DC6:  STA WTDOG               ;NOW NOT
L7DC9:  BNE STEST1_31           ;COUNT FOR 256/3000 OF A SECOND
L7DCB:  DEY
L7DCC:  BPL STEST1_31           ;8*256/3000 OF A SECOND
L7DCE:  STX $2C01               ;TURN OFF SOUND
L7DD1:  LDY #$08

STEST1_35:
L7DD3:  BIT THRKHZ              ;COUNT 3KHZ SIGNALS
L7DD6:  BPL STEST1_35

STEST1_36:
L7DD8:  BIT THRKHZ
L7DDB:  BMI STEST1_36
L7DDD:  DEX
L7DDE:  STA WTDOG               ;NOT NOW
L7DE1:  BNE STEST1_35           ;COUNT TIL 256/3000 OF A SECOND
L7DE3:  DEY
L7DE4:  BNE STEST1_35           ;COUNT TIL 8*256/3000 SECONDS
L7DE6:  TAX                     ;SET FLAGS
L7DE7:  BNE STEST1_20           ;MORE TO COME

STOP:
; [note] Spin until the self-test switch is pushed
L7DE9:  STA WTDOG               ;NO BITING NOW
L7DEC:  LDA STSTSW
L7DEF:  BMI STOP                ;WAIT UNTIL STEST SWITCH IS PUSHED

STOP_10:
L7DF1:  BPL STOP_10             ;START ALL OVER - WITH WATCHDOG

;-----------------------------------------[ ROM CHECKSUM ]------------------------------------------

STEST3:
; [note] Checksum the ROMs and test the bank select
L7DF3:  LDA #$00                ;CKSUM ALL ROMS
L7DF5:  TAY
L7DF6:  TAX
L7DF7:  LDA #$48

STEST3_5:
L7DF9:  STA $0A
L7DFB:  LDA #$07                ;8 PAGES TO TEST
L7DFD:  STA TEMP2
L7DFF:  LDA #$55                ;STARTING PATTERN
L7E01:  CLC

STEST3_10:
L7E02:  ADC (TEMP1),Y
L7E04:  INY
L7E05:  BNE STEST3_10           ;DO ONE PAGE
L7E07:  INC $0A
L7E09:  DEC TEMP2
L7E0B:  BPL STEST3_10           ;DO 8 PAGES
L7E0D:  STA R0,X                ;STORE 6 CKSUMS STARTING AT R0
L7E0F:  ORA CKERR               ;KEEP ERROR FLAGS
L7E11:  STA CKERR
L7E13:  INX
L7E14:  STA WTDOG               ;WHAT HAVE YOU BEEN TYPING ON THESE, LINDA?
L7E17:  LDA $0A
L7E19:  CMP #$58
L7E1B:  BCC STEST3_5            ;CKSUM 4800 TO 5800
L7E1D:  BNE STEST3_20           ;THEN SKIP TO 6000
L7E1F:  LDA #$60

STEST3_20:
L7E21:  CMP #$80
L7E23:  BCC STEST3_5            ;CKSUM 6000 TO 8000
L7E25:  STA $0300               ;200=0 AND 300=80
L7E28:  STA BNKSEL              ;SWITCH TO PLAYER 2
L7E2B:  CMP OBJ
L7E2E:  BEQ STEST3_25           ;BANK SELECT APPEARS OK
L7E30:  INC XT                  ;ERROR

STEST3_25:
L7E32:  LDA $0300
L7E35:  BEQ STEST5
L7E37:  INC XT                  ;ERROR

;----------------------------------------[ DISPLAY HANDLER ]----------------------------------------

STEST5:
; [note] Self-test display loop: one 16 ms pass
L7E39:  LDA #$10
L7E3B:  STA VGSIZE              ;SET CHARACTER SIZE
L7E3D:  STA BNKSEL              ;SWITCH TO PLAYER 1 CONTROLS
L7E40:  LDX #$24                ;THIS IS SET FOR 16MS BEST CASE

STEST5_5:
L7E42:  LDA THRKHZ              ;WAIT THRU ONE 3KHZ CYCLE
L7E45:  BPL STEST5_5

STEST5_7:
L7E47:  LDA THRKHZ
L7E4A:  BMI STEST5_7
L7E4C:  DEX                     ;COUNTDOWN TO VECTORS REPEAT EVERY 16MS
L7E4D:  BPL STEST5_5

STEST5_8:
L7E4F:  BIT HALT                ;WAIT FOR HALT
L7E52:  BMI STEST5_8            ;WATCHDOG WILL RESET IF VECTOR GENERATOR IS LOST
L7E54:  STA WTDOG
L7E57:  LDA #$00
L7E59:  STA VGLIST
L7E5B:  LDA #$40
L7E5D:  STA $04

STEST6:
; [note] Self-test: read the switch, draw the option switches and checksum results
L7E5F:  LDA STSTSW
L7E62:  AND #$80                ;S.T. SWITCH
L7E64:  BNE STEST6_90           ;STAY IN SELF-TEST
L7E66:  STA $01FF               ;ENABLE NMI'S
L7E69:  JMP START               ;($6000) BEGIN GAME

STEST6_90:
L7E6C:  LDA XT
L7E6E:  BEQ STEST6_30
L7E70:  LDX #$CC
L7E72:  LDA #$57
L7E74:  JSR VGJSRL              ;($7A2A) JSRL BNKERR FOR BANK SELECT ERROR

STEST6_30:
L7E77:  LDX #$96
L7E79:  STX $0D                 ;STARTING Y VALUE FOR CHECKSUMS
L7E7B:  LDX #$05

STEST6_32:
L7E7D:  LDA R0,X
L7E7F:  BEQ STEST6_35
L7E81:  STX TEMP2               ;SAVE X
L7E83:  LDX $0D
L7E85:  TXA
L7E86:  SEC
L7E87:  SBC #$08                ;32 BELOW CURRENT LINE
L7E89:  STA $0D                 ;SAVE POSITION FOR NEXT LINE
L7E8B:  LDA #$20
L7E8D:  JSR VGAWT               ;($7AF7)
L7E90:  LDX TEMP2
L7E92:  LDY ROMX,X              ;GET X ADDRESS OF ROM
L7E95:  JSR VGCHAR              ;($7A0A) DISPLAY
L7E98:  LDX TEMP2
L7E9A:  LDY ROMY,X              ;GET Y ADDRESS OF ROM
L7E9D:  JSR VGCHAR              ;($7A0A) DISPLAY
L7EA0:  LDX TEMP2

STEST6_35:
L7EA2:  DEX
L7EA3:  BPL STEST6_32           ;LOOP THRU ALL CHECKSUMS
L7EA5:  LDA #$57
L7EA7:  LDX #$44
L7EA9:  JSR VGJSRL              ;($7A2A) JSRL TO TEST PATTERN
L7EAC:  LDA #$93
L7EAE:  LDX #$A0
L7EB0:  JSR VGAWT               ;($7AF7) POSITION BEAM
L7EB3:  LDX #$03                ;NO NEED TO WAIT

STEST6_28:
L7EB5:  LDA OPTN1,X             ;GO FROM SW1 TO SW8
L7EB8:  AND #$03
L7EBA:  STX TEMP2
L7EBC:  JSR VGBLNK              ;($7CC5)
L7EBF:  LDX TEMP2
L7EC1:  DEX
L7EC2:  BPL STEST6_28           ;LOOP THRU 8 SWITCHES
L7EC4:  LDA #$93                ;X POSITION
L7EC6:  LDX #$B0                ;Y POSITION
L7EC8:  JSR VGAWT               ;($7AF7) POSITION
L7ECB:  LDA #$07                ;RELEASE POKEY
L7ECD:  STA $2C0F
L7ED0:  STA $2C0B
L7ED3:  LDA OPTN5               ;GET COIN OPTIONS
L7ED6:  EOR #$FF
L7ED8:  STA TEMP2
L7EDA:  STA CMODE
L7EDC:  ASL A
L7EDD:  ROL A
L7EDE:  ROL A
L7EDF:  ROL A
L7EE0:  ROL $0D
L7EE2:  AND #$07                ;ISOLATE BONUS OPTIONS
L7EE4:  JSR VGBLNK              ;($7CC5) DISPLAY DIGIT FOLLOWED BY BLANK
L7EE7:  LDA $0D
L7EE9:  AND #$01                ;ISOLATE MIDDLE MECH MULTIPLIER
L7EEB:  JSR VGBLNK              ;($7CC5) DISPLAY DIGIT FOLLOWED BY BLANK
L7EEE:  LDA TEMP2
L7EF0:  LSR A
L7EF1:  LSR A
L7EF2:  AND #$03                ;ISOLATE RIGHT MECH MULTIPLIER
L7EF4:  JSR VGBLNK              ;($7CC5) DISPLAY DIGIT FOLLOWED BY BLANK
L7EF7:  LDA TEMP2
L7EF9:  AND #$03                ;ISOLATE COIN MODE
L7EFB:  JSR VGBLNK              ;($7CC5) DISPLAY DIGIT FOLLOWED BY BLANK
L7EFE:  JSR SINIT               ;($7C37)
L7F01:  LDY NHITS
L7F03:  LDA #$96
L7F05:  LDX #$94
L7F07:  INY
L7F08:  JSR LIVESS              ;($7C74) DISPLAY THEM
L7F0B:  LDA #$10
L7F0D:  STA VGSIZE
L7F0F:  LDA $FF                 ;BONUS?
L7F11:  BMI STEST6_27           ;NO BONUS
L7F13:  LDA #$8E
L7F15:  LDX #$83
L7F17:  JSR VGAWT               ;($7AF7)
L7F1A:  JSR BONDSP              ;($7C93) DISPLAY BONUS SCORE

STEST6_27:
L7F1D:  LDA PERR                ;ANY POKEY ERRORS?
L7F1F:  BEQ STEST6_25           ;NO
L7F21:  LDX #$CB
L7F23:  LDA #$F4
L7F25:  JSR VGADD2              ;($7CCC)

STEST6_25:
L7F28:  INC FRAME
L7F2A:  LDA FIRESW              ;IF ALL 4 BUTTONS ARE ON
L7F2D:  AND THRUST
L7F30:  AND ROTL
L7F33:  AND ROTR
L7F36:  BPL STEST6_11           ;THEY'RE NOT
L7F38:  BIT LPLAYR
L7F3A:  BMI STEST6_11           ;ALREADY ERASED
L7F3C:  STA EAFLG               ;SIGNAL TO ERASE
L7F3E:  STA LPLAYR              ;ONLY DO THIS ONCE
L7F40:  LDX #$15
L7F42:  STX EABC                ;21 BYTES
L7F44:  DEX
L7F45:  STX EAX                 ;START @ 20

STEST6_11:
L7F47:  LDA LPLAYR              ;ANY EA STUFF?
L7F49:  BEQ STEST6_29           ;NO. NO MESSAGES EITHER
L7F4B:  LDA EAFLG               ;ERASING OR WRITING?
L7F4D:  BEQ STEST6_29           ;NO
L7F4F:  LDA #$94
L7F51:  LDX #$72
L7F53:  JSR VGAWT               ;($7AF7)
L7F56:  LDX #$F2                ;SAY WE'RE ERASING
L7F58:  LDA #$57
L7F5A:  JSR VGJSRL              ;($7A2A)
L7F5D:  JSR EAUPD               ;($7B11) DO EA STUFF
L7F60:  LDA INTCT               ;NMI'S DON'T WORK IN SELF TEST
L7F62:  CLC
L7F63:  ADC #$04                ;SO FOOL EAUPD ROUTINE
L7F65:  STA INTCT               ;BY SAYING 4 INTERRUPS HAPPENED

STEST6_29:
L7F67:  LDA #$7F
L7F69:  TAX
L7F6A:  JSR VGSABS              ;($7A31) CENTER BEAM
L7F6D:  JSR VGHALT              ;($79EC) STOP BEAM

;------------------------------------------[ SWITCH TEST ]------------------------------------------

STEST7:
; [note] Self-test: clear the POKEY, read the player switches, drive the sound test
L7F70:  LDY #$08
L7F72:  LDA #$00

STEST7_1:
L7F74:  STA $2BFF,Y             ;CLEAR POKEY REGISTERS
L7F77:  DEY
L7F78:  BNE STEST7_1            ;LEAVE Y=0 WHEN DONE
L7F7A:  JSR SWCH                ;($7F94) GET PLAYER SWITCHES
L7F7D:  ORA $88
L7F7F:  ORA $87
L7F81:  ORA ASTERS
L7F83:  BEQ STEST7_25           ;NO DIFFERENCES
L7F85:  LDA #$A4                ;TURN ON SOUND

STEST7_25:
L7F87:  STA $2C01               ;VOLUME SELECT
L7F8A:  LSR A                   ;CLEAR BIT 7
L7F8B:  STA POKEY               ;FREQUENCY SELECT
L7F8E:  STA GOADD               ;START DRAWING NOW
L7F91:  JMP STEST5              ;($7E39)

SWCH:
; [note] Read all the switches for the self-test display
L7F94:  JSR SWCH_1              ;($7F97) DO THE FOLLOWING TWICE

SWCH_1:
L7F97:  LDX #$07                ;PUT 8 SWITCHES INTO ACC

SWCH_2:
L7F99:  ROL COINA,X             ;RL/RR/TH/S1/S2/CR/CC/CL
L7F9C:  ROR A
L7F9D:  DEX
L7F9E:  BPL SWCH_2
L7FA0:  JSR SWCH_4              ;($7FB4) COMPUTE DIFFERENCES
L7FA3:  LDX #$04                ;PUT 5 SWITCHES INTO ACC

SWCH_3:
L7FA5:  ROL HYPSW,X             ;SHLD/FIRE/DIA.STP./SLAM/SELFT
L7FA8:  ROR A
L7FA9:  DEX
L7FAA:  BPL SWCH_3
L7FAC:  STX BNKSEL              ;SWITCH TO PLAYER 2 FOR NEXT TIME
L7FAF:  LDX #$28

SWCH_5:
L7FB1:  DEX
L7FB2:  BPL SWCH_5

SWCH_4:
L7FB4:  TAX                     ;SAVE SWITCHES FOR A SEC.
L7FB5:  EOR a:R6,Y              ;COMPUTE DIFFERENCES
L7FB8:  STA a:ASTERS,Y          ;SAVE DIFFERENCES
L7FBB:  STX R6,Y                ;SAVE NEW READINGS
L7FBD:  INY                     ;UP TO NEXT VARIABLES FOR NEXT TIME
L7FBE:  RTS                     ;RECURSE/EXIT AS RQD.

STEST7_FILL:
; placed by hand: DSTTST.MAC:460 `.REPT STEST7+81.-. / .BYTE -1 / .ENDR  ;FILLER SO ADDRESS DON'T CHANGE`. Unlabelled padding that pins PKYTST to $7FC1; NAMED here
L7FBF:  .byte $FF, $FF          ;..

;------------------------------------------[ POKEY TEST ]-------------------------------------------

PKYTST:
; [note] POKEY test, and the rock-speed initialiser
L7FC1:  LDA FRAME               ;GET FRAME #
L7FC3:  AND #$03                ;ISOLATE LSB'S
L7FC5:  TAX                     ;INDEX
L7FC6:  LDA RANDOM              ;GET POKY'S RANDOM #
L7FC9:  STA $DC,X               ;SAVE IT
L7FCB:  LDY #$00                ;CLEAR ERROR COUNTER (WILL ALWAYS GET 1 ERROR)
L7FCD:  LDX #$04                ;SET LOOP COUNTER

PKYTST_2:
L7FCF:  CMP PERR,X              ;HOW DOES THIS MATCH WITH THE LAST 3?
L7FD1:  BNE PKYTST_1            ;DIFFERENT
L7FD3:  INY                     ;SAME COUNT IT

PKYTST_1:
L7FD4:  DEX
L7FD5:  BNE PKYTST_2
L7FD7:  CPY #$04                ;SET CARRY
L7FD9:  LDY #$0A                ;MINIMUM VELOCITY NORMAL
L7FDB:  LDX #$F6
L7FDD:  LDA OPTN5               ;S/B 0
L7FE0:  ROR A
L7FE1:  BEQ PKYTST_3
L7FE3:  LDX #$FB                ;MAKE THE GAME EASY
L7FE5:  LDY #$05

PKYTST_3:
L7FE7:  STX RVELM               ;+
L7FE9:  STY RVELP               ;-
L7FEB:  STA PERR                ;ERROR CODE
L7FED:  RTS

ROMX:
; placed by hand: DSTTST.MAC:502 `ROMX: LET R,N,D,E,H,J`, the ROM position letters the checksum display prints, encoded (letter-'A'+11)*2: 38 30 1C 1E 24 28
L7FEE:  .byte $38, $30, $1C, $1E, $24, $28 ;80..$(

ROMY:
; placed by hand: DSTTST.MAC:503 `ROMY: NUM 2,2,1,1,1,1`, the matching position digits, encoded (n+1)*2: 06 06 04 04 04 04
L7FF4:  .byte $06, $06, $04, $04, $04, $04 ;......

VCTRS:
